quests[30261] = { id = 30261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll Club: Serpent's Spine", description = "Get to the bottom of the wall in the fastest time possible.\n\nSpeak to me when you're ready to roll.", sourceObjective = "Complete the Serpent's Spine roll course.", progress = "Ready to roll?", completion = "When they built the wall, I don't think they knew we'd be using it for this.", sourceObjectiveStatus = "unverified-source-field" }
quests[30263] = { id = 30263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing in the Forest", description = "The Shao-Tien are on their heels. Most of them retreated to Winterbough Glade after their last defeat. We should press the advantage.\n\nTake the fight to these mogu in the clearing to the northwest. Let us leave them no minute of rest as long as they remain in the Vale.", sourceObjective = "Kill 6 Shao-Tien mogu in Winterbough Glade.", completion = "We must seize our advantage when an opportunity presents itself. We must make the Shao-Tien pay for every moment they remain in the Vale.\n\nYou've done well this day, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30264] = { id = 30264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy at the Gates", description = "The mantid forces are pouring against the wall. I've arranged for some flying serpents to cut away at their forces from the air.\n\nWould you be willing to take the reigns on one of them?", sourceObjective = "Use a Shado-Pan Sky Serpent to kill 60 Krik'thik attackers, 3 Krik'thik War Wagons, and 3 Krik'thik Catapults.", progress = "The mantid sense our weakness during the mogu attacks. They're hoping to take us off-guard. They underestimate me.", completion = "Kun tells me you were amazing out there. You impress my man, you impress me.\n\nGood work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30265] = { id = 30265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparkle in the Eye", description = "I've been staring down into the waters of the lake, pondering life, love, and everything beautiful, and suddenly I realized that the sparkles in the water aren't just a reflection of my radiant personality, there are actually some sort of shining objects down there! Surely valuable.\n\nWould you mind taking a drip and relieving the lake's depths of its mysterious sparkles? Pretty please?", sourceObjective = "Recover 8 Shining Rubies.", progress = "What were these mysterious sparkles? I've been dying with curiosity. Coins? Goblets? A dozen discarded wedding rings?", completion = "Rubies! Valuable, yes! Suggestive of an interesting backstory involving a dozen broken-hearted brides? Likely not. Still, quite the find!\n\nThank you my marvelously benevolent friend! You have saved me some awkwardly wet robes with your generous aquatic ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[30266] = { id = 30266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodied Skies", description = "We have cannons set up on the top of the towers flanking the main gate. They are our best method to clear the skies when the flying mantid try to pass over the wall, like they are now.\n\nLooks like you're on, {name}.", sourceObjective = "Kill 30 Krik'thik Swarmers using a Setting Sun Turret.", progress = "The wall... the wall is where we all met.  Better times past.", completion = "You've got good aim, {class}. I'll remember that the next time the fliers come.", sourceObjectiveStatus = "unverified-source-field" }
quests[30267] = { id = 30267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watery Woes", description = "I love fishing. I'd be enjoying myself much more, however, if I had my bait and my lures. They were thrown away in a... a misunderstanding with my wife, Rin.\n\n<Gladecaster Lang sighs.>\n\nShould I let a whole day of fishing be ruined, just because of a little domestic squabble? No! All I need is bugs and feathers, after all, and this glade is filled with those two things.\n\nCare to help a fisherman out?", sourceObjective = "Obtain 18 Glade Glimmers and 5 Spindly Bloodfeathers.", progress = "I refuse to not fish. Fishing's who I am!", completion = "Finally, someone who understands me. Fishing is what it's all about, right?\n\nMaybe I should leave New Cifera... just pack up my things and join the Anglers, down in the south. Of course, I couldn't leave my family behind...\n\nBut still... a pandaren can dream, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[30268] = { id = 30268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Murksweats", description = "Take a good look. The river nearby is swarming with these snakes. Their venom causes a condition the locals call \"the murksweats.\"\n\nSeveral refugees were bitten as they fled the temple and have already begun to show symptoms: nausea, vomiting, and intense sweating as the body rejects all fluids, causing dehydration and potentially death.\n\nWe are administering anti-venom as quickly as possible, but we'll need more venom glands. Don't bother removing the glands yourself - just bring back the whole head.", sourceObjective = "Gather 6 Murkscale Heads from Murkscale Strikers in Krasarang River.", progress = "<Anduin is focused intently on his hands, swiftly carving venom glands from the snakes.>\n\nInside the jaw... two inches behind the second set of fangs...", completion = "Thank you, {class}. I knew you'd be hardy enough to handle it.\n\nJudging by the sounds coming out of these refugees, I would not wish the murksweats on my worst enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[30269] = { id = 30269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsafe Passage", description = "As we say at the temple: \"Never fight a tiger with a hozen on your back.\"\n\nWe will deal with the sha, but first we must see to the more immediate... nuisance.\n\n<Koro slams the writhing saurok HARD against the stone.>\n\nGroups of refugees from the temple are heading for a camp to the north, but they're being ambushed by saurok. Help me see the next group to the camp and we'll figure out our next move from there.", sourceObjective = "Help Koro Mistwalker escort a group of refugees from the Temple of the Red Crane to Crane Wing Refuge. Speak with Koro first to begin.", completion = "Thank you, {name}. We would not have made it without your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[30270] = { id = 30270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Riverblades", description = "\"A hooded falcon catches no quarry.\"\n\nThis is one of the first mantras we teach young monks at the temple. It means that even a foe as swift and lethal as a falcon can be neutralized by depriving its senses.\n\nThe saurok have scouts all over the region acting as eyes for their raiding parties.\n\nIt's time we put their eyes out, don't you think?", sourceObjective = "Kill 8 Riverblade Pathstalkers in the areas surrounding Crane Wing Refuge.", completion = "Well done. I only wish I could have accompanied you...\n\nThe blood on these hand-wraps is not my own, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[30271] = { id = 30271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sha Can Awe", sourceObjective = "Kill sha near 10 Hopeless Monks or Acolytes to inspire them.", progress = "Look for Crane Wing pandaren who are falling to despair and slay sha near them while I support you!", completion = "Honestly, I'm a little surprised that worked.\n\nPandaria is proving to be a land where the lines between metaphor and reality are blurred.", sourceObjectiveStatus = "unverified-source-field" }
quests[30272] = { id = 30272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking the Rain", description = "Now as for that \"striking the rain\" part... well, sometimes you have to.\n\n\"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the eye.\"\n\nThere seems to be no end to the sha pouring out of the temple. But in order to see beyond the veil of despair, you must carve through it.\n\nWith any luck, you'll find a sun behind the clouds...", sourceObjective = "Kill 18 Haunts of Despair at the Temple of the Red Crane.", progress = "We shouldn't press further into the temple before clearing out some of the sha presence outside.", completion = "You know something, {name}? We make a pretty good team!", sourceObjectiveStatus = "unverified-source-field" }
quests[30273] = { id = 30273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the House of the Red Crane", sourceObjective = "Enter the basement of the Temple of the Red Crane and defeat the Sha of Despair.", completion = "You have vanquished the Sha of Despair. My order can handle the remaining cleanup from here.\n\nIt seems the time has finally come to face the consequences of Shaohao's actions.\n\nThis conflict has been a long time coming - the arrival of your people was merely a catalyst. Now, your help will be necessary if Pandaria is to survive.", sourceObjectiveStatus = "unverified-source-field" }
quests[30274] = { id = 30274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcanic Oubliette", description = "An Alliance member? Here? Elune be praised.\n\nMy team has encountered a snag. We opened a portal to this land using some ancient scrolls we had found that predated Azshara's rule.\n\nUnfortunately, the coordinates provided on the tablets were warded and the portal that meant to take us to our destination landed us in this oubliette.\n\nWe have been trapped here for days, and it is slowly leaching our energies to power itself.\n\nCan you find the nearby shackles that bind the oubliette and disable them?", sourceObjective = "Find and disable the 3 Oubliette Shackles.", completion = "Fabulous! Your timing was impeccable. Another day in there and I think we would have wasted away to nothing.\n\nNow we can continue our search for the Pools of Youth!", sourceObjectiveStatus = "unverified-source-field" }
quests[30275] = { id = 30275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crocolisk Tale", description = "How could this crocolisk have grown so large?\n\nCertainly, rumors exist of very old crocolisks that have grown to enormous sizes... but this female can't be more than a dozen years old.\n\nPerhaps someone in New Cifera can shed some light on the subject.", sourceObjective = "Bring the Enormous Crocolisk Tail to Yan at New Cifera in the Valley of the Four Winds.", progress = "What's that you've got there?", completion = "This tail came from a crocolisk? Funny, we don't get many crocs this far upstream.\n\nHave you seen some of the enormous fruits and vegetables that our farmers can grow? Your crocolisk grew so large for the same reason - there's something in the water.\n\nWhat it is, we're not quite sure... but we count it among our blessings. Humongous vegetables are great. The odd giant crocolisk every now and again is really just a side effect.", sourceObjectiveStatus = "unverified-source-field" }
quests[30277] = { id = 30277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbling Hall", description = "An ancient mogu artifact has been uncovered in the Guo-Lai Vault, beyond the Hall of Statues. We've made repeated attempts to retrieve it, but none have been successful.\n\nWe cannot let this artifact fall into the hands of the Shao-Tien. I need someone capable to retrieve it, and quickly.\n\nAre you in?", sourceObjective = "Retrieve the Ancient Guo-Lai Artifact.", progress = "Have you recovered the artifact yet?", completion = "When everyone else lets me down, you follow through. That's why I like you.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30278] = { id = 30278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30279] = { id = 30279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30280] = { id = 30280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunder Below", description = "Roars have been echoing out from inside the Guo-Lai Halls. The mogu have awakened some ancient beast, and it will not be long before they attempt to release it upon my men.\n\nFind your way to the Hall of the Serpent and slay the beast before it can be unleashed upon us. I would trust no other with such a dangerous and important task.", sourceObjective = "Slay Milau.", completion = "You accomplish what I doubt I could even overcome myself. I am humbled by your valor.", sourceObjectiveStatus = "unverified-source-field" }
quests[30281] = { id = 30281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Approach", description = "<He leans over and draws a picture of what can only be a mogu, points towards the lake to the west, drags the blunt side of his dagger across his throat, and looks at you expectantly. It seems he wants you to kill mogu at Whitepetal Lake.>", sourceObjective = "Kill 6 Shao-Tien mogu at Whitepetal Lake.", completion = "The mogu numbers seem to be sufficiently thinned.", sourceObjectiveStatus = "unverified-source-field" }
quests[30282] = { id = 30282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Away the Filth", description = "The mogu have erected their filthy banners around the lake to the west, claiming it as their own. Take this torch and show them what we think of their banners.", sourceObjective = "Burn 10 Shao-Tien Banners.", completion = "I'll take the smoke on the horizon to mean that they've received our message. Good.", sourceObjectiveStatus = "unverified-source-field" }
quests[30283] = { id = 30283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smashing Impression", description = "Sometimes I feel sorry for these mogu... maybe ripping out the spirits of other races is just their way of coping with family issues at home? Maybe we should be more sympathetic to where all this aggression stems from?\n\nOr we could just smash all their soul-stealing ritual objects down at the lake. That sounds more fun to me personally.", sourceObjective = "Destroy the Shao-Tien Ritual Statues.", completion = "If they come asking who rudely crushed all their little statuettes, I'll tell them it was you.\n\nNot that I don't appreciate your help. You're lovely.", sourceObjectiveStatus = "unverified-source-field" }
quests[30284] = { id = 30284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Pointy Teeth", description = "The water has been frothing with danger this day! Some sort of swarming, meat-eating fishy nastiness has taken up residence in our lake! Deplorable. And just when I was considering stripping down to my nothings to take a mid-day dip!\n\nYou are adept in the ways of slaughtering any manner of nasty, are you not? Would you put your skills to use this day, in the name of pandaren everywhere desiring a swim?\n\nIt's a truly noble cause, especially with me among their ranks!", sourceObjective = "Kill 9 Knifetooth Swarmers.", progress = "The bubbling water and occasional splotch of redness floating to the top suggest to me that these vicious fish are still at large!\n\nExercise your nastiness upon them, friend!", completion = "Aren't you just the sweetest thing?! I do rather like you.\n\nI'm going to take that afore-mentioned dip now. I'll be modest and delay my disrobing until you depart, as a repayment for your kindness.\n\n...you're missing quite the sight though, I must say.", sourceObjectiveStatus = "unverified-source-field" }
quests[30285] = { id = 30285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wu Kao Scouting Reports", description = "There were some scouting reports unaccounted for after the attack. If we're lucky, they're still out in the village, but the mogu may have gotten their hands on some of them as well.\n\nIf you could bring back any scouting reports you find, it would definitely put my mind at ease. We can't afford to let the mogu in on our positions or any of the artifacts we've found, lest the men be in even more danger than they already are.", sourceObjective = "Recover 3 Wu Kao Scouting Reports.", progress = "Any luck finding those reports?  I'm worried for the safety of our men in the field if too much information falls into mogu hands.", completion = "You are very kind, {name}. Thank you for putting my mind at ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[30286] = { id = 30286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backed Into a Corner", description = "Many villagers are cornered and scared, unable to defend themselves. You will need to defend them. Rescue them.\n\nGo quickly friend, save as many as you can!", sourceObjective = "Rescue 6 Cornered Mistfall Villagers.", progress = "The vale has become a dangerous place with the mogu forces on the move. We will need to teach these villagers to properly defend themselves.", completion = "We've holed up everyone we can in the bar. We should be able to protect them for now.\n\nThank you again for your help, {name}. You always seem to be there right when we need you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30287] = { id = 30287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", sourceObjective = "Kill 6 Shado-Tien attackers in Mistfall Village.", completion = "Rook can handle rest of mogu.  Thanks for help.  Good man.", sourceObjectiveStatus = "unverified-source-field" }
quests[30288] = { id = 30288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Town, It's On Fire Again", description = "I don't know if you noticed, but my town is on fire... again.\n\nWe have water buckets all over town, but no one can get out to put out the fires. Please, please, help us!", sourceObjective = "Use Mistfall Water Buckets to douse 60 fires.", progress = "We lost our homes in Kun-Lai already, we can't lose these homes too!", completion = "I really wish you guys would stop throwing the buckets at the fire too... just the water would have been fine.\n\nReally though, it's a relief that you're here to help. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30289] = { id = 30289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freeing Mind and Body", description = "Mogu stealing peoples minds! Making them do evil things.\n\nDon't kill them, just kill the mogu, then they forget about all the mogu mind stealing and stop being evil. You should fix people like Rook is.", sourceObjective = "Free 6 Dominated Guards by killing their controllers.", progress = "More villagers left that need to forget about mogu mind tricks. Please help Rook.", completion = "Lots of villagers inside and safe now. You do good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30290] = { id = 30290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebound Killers", description = "Mogu stone dog creatures chasing villagers and hurting them. Rook try to smash some, but they too fast.\n\nYou help smash some too?", sourceObjective = "Kill 8 Stonebound Quilen.", progress = "More dog things all over village. Still need more help please.", completion = "Yes! You faster than rook. Do good!\n\nThank you, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30291] = { id = 30291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning Display", description = "I've been talking to Tantan here... again... and he insists that fishing is some kind of fabulous. I was skeptical, but I gave it another go. I'm not a big fan of that whole holding a stick and waiting method though, so I tried something a bit more direct.\n\nWould you be a doll and go collect any of the still intact fish floating belly up in the lake for me?", sourceObjective = "Collect 12 Stunned Whitepetal Carp.", progress = "As an added bonus, my method ensures they're already cooked! If that's not a marvel of modern efficiency, I don't know what is.", completion = "Marvelous! You're quite the efficient fetcher.\n\nI'm grateful that you don't mind getting that fancy armor of yours wet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30292] = { id = 30292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rude Awakenings", description = "The mogu are taking over the minds of the saurok at the lake to our west and turning them against us! The thing is, they were already against us, so I'm not sure they really thought this thing through fully.\n\nAnyway, Anji's the fighter in this pair, I'm more the lover, so I'm looking for someone to do all the weapon swinging and spell flinging and war crying and such.\n\nCan you go kill some saurok for me?", sourceObjective = "Kill 8 Dominated Paleblade Flesheaters.", completion = "You smell of saurok and mogu. Not a terribly pleasant mix, my friend. But it suggests to me that your task is done, and for that I thank you.\n\nMay we meet again soon under better-smelling terms.", sourceObjectiveStatus = "unverified-source-field" }
quests[30293] = { id = 30293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Enemy Hands", description = "The Shao-Tien Mindbenders have taken over the minds of our defenders down at Whitepetal Lake to the west. Get down there and kill the mogu that are controlling them, but don't kill the defenders! Killing their captors should free them from their mind control.\n\nSooner would be better. Anji might try to go down there to help soon, and her ability to restrain herself when in the heat of things is not one of the qualities I married her for.", sourceObjective = "Beat 8 Possessed Whitepetal Defenders until they're freed of mogu possession.", progress = "Or you could just dispel them if that's your thing. You seemed like the type that might want to beat some people up though.", completion = "More than one pandaren is thankful for your help today, that's for sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[30294] = { id = 30294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Comforts", description = "The mindbenders at Whitepetal Lake are pulling the spirits from the corpses of the dead to inflict who-knows-what kind of torments upon them.\n\nI've written on this scroll a rite that will release their spirits from their bodies and send them on their way. Where they go and what happens to them from there I don't know, but it will at least free them from the cruel hands of the mogu.\n\nRead this rite over any of the fallen you find. We'll recover their bodies later.", sourceObjective = "Read the Rite of Release at the bodies of 6 Fallen Golden Lotus Defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[30295] = { id = 30295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn-in Quest Test Case" }
quests[30296] = { id = 30296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaohun the Soul-Severer", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", sourceObjective = "Kill Gaohun the Soul-Severer.", progress = "Mogu leader still shouting orders from up the hill. Friend help Rook make him quiet?", completion = "Leader gone. People safe. Rook save village. And friend save village too. Thank you, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[30297] = { id = 30297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baolai the Immolator", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", sourceObjective = "Kill Baolai the Immolator.", progress = "Mogu leader still shouting orders from up the hill. Friend help Rook make him quiet?", completion = "Leader gone. People safe. Rook save village. And friend save village too. Thank you, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[30298] = { id = 30298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Painting the Ruins Red", description = "The mogu think they can inhabit these ruins uncontested. Let's show them the error in their ways.", sourceObjective = "Kill 8 mogu in the Ruins of Guo-Lai.", progress = "They underestimate us at every turn, just as they underestimated us during the uprising so many years ago.", completion = "Their foothold in these ruins shall not last the night.", sourceObjectiveStatus = "unverified-source-field" }
quests[30299] = { id = 30299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Stone Unturned", description = "The mogu have forced spirits into their old statues to bring them to life, control them, and turn them against us.\n\nThe only way to free the bound spirits is to destroy their vessels.", sourceObjective = "Destroy 6 Mogu Statues.", completion = "Your efforts here make all the difference. Thank you so much for your help, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30300] = { id = 30300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Success", description = "The mogu have taken prisoners. They'll be tortured or worse.\n\nFind any way you can to free them from their cages.", sourceObjective = "Find a Shao-Tien Cage Key and free 6 Golden Lotus Prisoners.", progress = "I'd rather die than live as a mogu prisoner. They are not kind captors.", completion = "Many of those you saved are back here in camp recovering. You surely have their gratitude, and mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[30301] = { id = 30301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offering a Warm Welcome", description = "There is no more sure message we can send them then to burn the tents the sleep in.\n\nScour the ruins. Destroy every tent you find.", sourceObjective = "Burn 6 Mogu Tents in the Ruins of Guo-Lai.", completion = "Smoke in the distance tells me that you were successful. Good work, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30302] = { id = 30302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imperion Threat", description = "Scouts spotted a Shao-Tien Imperion entering the Guo-Lai Halls. I need someone I can trust to make sure he doesn't come out of there alive.\n\nI think you're the {class} for the job.", sourceObjective = "Kill the Shao-Tien Imperion.", progress = "The mogu have repeatedly sent groups of their stronger warriors into those chambers.  There is definitely something they want inside.", completion = "You haven't let me down.  I won't forget that.", sourceObjectiveStatus = "unverified-source-field" }
quests[30304] = { id = 30304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard as a Rock", description = "Hey! You know what awesome thing happened to me this morning?\n\nI was strolling through the ruins with Anji, eyes on the ground so I wouldn't step on anymore of those creepy spider pods, when one of the statues came to life and tried to smash me!\n\nAnji ended up doing the smashing. But I'm not satisfied. I think that you should go out there and smash all the statues, whether they're moving or not. It's the only way to be sure.", sourceObjective = "Destroy 10 Mogu Statues.", progress = "I'll never trust a statue again.", completion = "Your ruins vandalizing efforts are appreciated, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30305] = { id = 30305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Knows What He's Doing", description = "You know He Softfoot? Sneaky guy, don't talk much. He put traps all over ruins for mogu. He said Rook just need to trick mogu into traps. Rook don't really know how.\n\nMaybe you do it? You find traps, you get bad guys into traps? Can you not tell He though, please?", sourceObjective = "Lure 8 enemies into He's Poison Traps.", progress = "You were going to do trap thing for Rook, yes?  Please?", completion = "You really good friend. Rook like you. Thank you, good friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[30306] = { id = 30306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Ring", description = "We have some fresh trainees that are far from being a danger to you, but in numbers, they may prove enough of a challenge. And if not, they could use the lesson in humility.\n\nStep into the battle ring when you're ready. Don't go easy on them.", sourceObjective = "Defeat 20 Shado-Pan Trainees in the Battle Ring.", progress = "Step into the ring. Show them how a real {class} fights.", completion = "Very impressive. It seems they have much learning to do. I'll see to that.", sourceObjectiveStatus = "unverified-source-field" }
quests[30307] = { id = 30307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Vigil", description = "Good to have you with us, {class}. If you're joining the fight, I need more men out up at the Golden Stair to clear out the mogu setting up base there.\n\nCan I count on you?", sourceObjective = "Kill 8 Shao-Tien mogu on the Golden Terrace.", progress = "They have countless tombs of stone warriors to bring to bear against us.\n\nWe have the endless enduring nature of the {race} spirit to hold them back.", completion = "We hold this line. It does not matter how long they come, we hold this line.", sourceObjectiveStatus = "unverified-source-field" }
quests[30308] = { id = 30308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Hard Quilen", description = "Leven always says the only good quilen is a dead quilen, and I'm inclined to agree. You here to aid the cause?", sourceObjective = "Kill 6 Granite Quilen.", progress = "Years on the wall have prepared me for anything the mogu can throw at us. This war will be short lived.", completion = "Less of those beasts on the field always cheers my day up a bit. Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[30309] = { id = 30309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set in Stone", description = "The mogu have been sending their narcissistic stone effigies onto our battlefield today. They're brining them to life up on the Golden Stair.\n\nThe bigger they are, the harder we hit'm. You in?", sourceObjective = "Destroy 6 Mogu Effigies.", completion = "There's a satisfying amount of ruble strewn across the field today. A sign of your good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30310] = { id = 30310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thundering Skies", description = "The mogu have bent the will of sky serpents and turned them against us.\n\nThe defenders won't fare well against them, but you would. Head northwest towards the Golden Stair and remove them from the sky.", sourceObjective = "Kill 3 Subjugated Serpents.", completion = "Quite the battle! I think your feat has boosted morale among the troops a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30311] = { id = 30311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Standards", description = "If I had to pick the most important quality for a battle standard, it would be that it's standing up... and not on fire, but mostly the first one. So needless to say, I'm a bit concerned about our standard situation at the moment.\n\nIf some unknown {class} were to be so kind as to take a walk out on the battlefield to our northwest and stand our standards back up, both myself and my extremely sexy yet somewhat commanding wife would be very grateful.", sourceObjective = "Erect 6 Golden Lotus Standards.", sourceObjectiveStatus = "unverified-source-field" }
quests[30312] = { id = 30312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Given a Second Chance", description = "A foolish contingent attempted to mount an offensive on the Golden Stair through the eastern pass, and were bombarded by cannons. Those that made it back are in bad shape, and there are still wounded out in the field.\n\nHere are some bandages. Use these, or any other healing skills you possess, and help get our wounded defenders back to safety.\n\nPlease hurry, there is little time.", sourceObjective = "Heal 6 Wounded Defenders.", progress = "There are more injured in need of attention. Please help if you can.", completion = "The men you healed made it back safely.\n\nThank you, kind friend. Truly.", sourceObjectiveStatus = "unverified-source-field" }
quests[30313] = { id = 30313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Moving Mists", description = "<He looks down at the dead fog creature at his feet, looks up at you, then points out into the mists surrounding the lake. It seems he wants you to find and kill more of these fog creatures.>", sourceObjective = "Kill 8 Fog Walkers.", progress = "<He stares at you blankly.>", completion = "<He pats you on the shoulder and nods his thanks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30314] = { id = 30314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Displaced Paleblade", description = "<He looks down at the dead saurok at his feet, looks up at you, then points out down the lake shore. It seems he wants you to find and kill more of these saurok.>", sourceObjective = "Kill 8 Paleblade Saurok.", progress = "<He stares at you blankly.>", completion = "<He smiles at you and nods his thanks.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30315] = { id = 30315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Normal Quest Test Case", description = "Yes?", sourceObjective = "Give me stuff.", sourceObjectiveStatus = "unverified-source-field" }
quests[30316] = { id = 30316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Longshot", description = "I would not normally ask this of grizzle {class} such as you, but since you are to be on the battlefield below the Golden Stair anyway, would you recover spent arrows for the archers?", sourceObjective = "Recover 12 Spent Shado-Pan Arrows.", sourceObjectiveStatus = "unverified-source-field" }
quests[30317] = { id = 30317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water, Water Everywhere", description = "How'd you like to make yourself useful?\n\nThe season's been awful dry lately. I need someone to water the crops out in the Heartland. Here's the thing: I need you to water ALL of the crops.\n\nI keep a few kites with Wing Nga, the flightmaster across the way. Grab one of those kites, then throw water on any areas that look dry and dusty.", sourceObjective = "Speak with Wing Nga to borrow a kite, then throw water onto 35 Dusty Spots in the Heartland.", progress = "Just come back when you're done. And don't break any of my kites.", completion = "Hmph! I knew you were a good waterer when I first saw you. You've got good watering arms.", sourceObjectiveStatus = "unverified-source-field" }
quests[30318] = { id = 30318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Chicken", description = "Say, you there! {name}, was it? I've got a problem, and I need someone with better legs than mine to help me solve it.\n\nMy prize-winning chicken has flown the coop! Now she's out in the open, mingling with the other hens, wild birds, and... <gulp> ill-intentioned roosters.\n\nMy farm is west of here, south of the Skyrange. Could you find her, and bring her back to me?", sourceObjective = "Pick up Hillpaw's Chickens until you find his Prize-Winning Chicken.", progress = "I swear, she's never done this before.", completion = "You found her! You've got an eye for fowl, kid.\n\nI'll hold onto her for now. Don't worry, I'll make sure she's punished later.", sourceObjectiveStatus = "unverified-source-field" }
quests[30319] = { id = 30319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Problems", description = "One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost field. I understand he's had some problems with pests.\n\nHe's got plenty of pesticide to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the marmots.\n\nWould you lend him a hand? With rampant hozen and virmen attacks, I can't afford to lose crops to simple pests.", sourceObjective = "Speak with Wika-Wika, then stomp on 25 Black-Nose Marmots.", completion = "Well, good. That that's taken care of. Neatly done, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30320] = { id = 30320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Spirits", description = "I came upon one of the Shao-Tien Soul-Render's daggers. It radiates a strong magic. I've been told it should allow you to enter their spirit vortexes.\n\nThe mogu use these to harvest spirits and bind them to their will, but I'm hoping you can use it to free the spirits.\n\nEnter any of the spirit vortexes you can find up on the Golden Stair, and free all the captive spirits you find.", sourceObjective = "Enter Spirit Vortexes and free 15 pandaren spirits inside.", progress = "The mogu are able to force {race} spirits into inanimate objects and bend them to their will, but the spirits still yearn to be free. This may be the tool we need to offer them that freedom.", completion = "Very good! I'll hold onto this dagger. Perhaps we will get the chance to make more use of it later.\n\nThank you so much, my friend. You have a good heart.", sourceObjectiveStatus = "unverified-source-field" }
quests[30321] = { id = 30321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed War II", description = "Ssshhay... d'you know that guy over on the farm, with the... the *hic*... the weed problem? Gai Lan, I think his name was. I love that guy, man.\n\nAnywayshh, he said that if I *hic* sent an adventurer over to go pick his weeds, he'd get me some ale.\n\nIt's jusht a few weeds, not too many, probably.\n\n*hic*", sourceObjective = "Speak to Gai Lan, then pick 100 Weeds on his farm. You can pick Weeds while mounted.", progress = "What time is it?", completion = "Thanks, mishter *hic* {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30322] = { id = 30322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Money Matters", description = "I love working in the market, although there's one aspect of this job I really dislike: collecting debts.\n\nWhile most pandaren debts are simply due to laziness, there are a few unsavory characters around town who simply don't want to pay, and there's some who are just too poor.\n\nA few people here in town owe me money. Could you go talk to them, and remind them about what they owe?", sourceObjective = "Obtain Spicemaster Jin Jao's Payment, Trader Jambeezi's Payment, Innkeeper Lei Lan's Payment, and Lolo Lio's payment.", progress = "You know, it's kind of nice having a thug... er, I mean, {class}... like you around.", completion = "I'm glad that nasty business is over with. Nobody gave you any trouble, did they?", sourceObjectiveStatus = "unverified-source-field" }
quests[30323] = { id = 30323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Don't Even Wear Them", description = "A few weeks ago, a group of those jumpy little Springtail virmen broke into my lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but they still have most of my collection.\n\nIf you're headed up to the Springtail Crag, in the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry back.", sourceObjective = "Obtain a Stolen Circlet, a Ransacked Ring, and a Burglarized Bracelet.", progress = "Can you believe how irresponsible and juvenile those virmen are? Don't they know how much that jewelry COST?", completion = "Oh, {name}! I'd kiss you right here and now if you weren't... well, if you weren't covered in virmen dust.\n\nThanks, though!", sourceObjectiveStatus = "unverified-source-field" }
quests[30324] = { id = 30324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not in Chee-Chee's Backyard", description = "Not all hozen are the same. Chee-Chee's tribe was forest hozen... came from Jade Forest. Pretty easy to get along with.\n\nThe Kunzen invaders... they come from mountains, far to the north. Not nearly as nice as Chee-Chee.\n\nThey come into our green land, take our things, leave big mess behind.\n\nChee-Chee wants to kill them. You like to help?", sourceObjective = "Kill 8 members of the Kunzen tribe in the Kunzen Village.", completion = "Great! Chee-Chee knew you could do it!", sourceObjectiveStatus = "unverified-source-field" }
quests[30325] = { id = 30325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where It Counts", description = "I've been watching those Kunzen hozen, and I've noticed a consistent pattern. Whenever they're getting ready to attack, they participate in strange, barbaric rituals around their totem.\n\nIf we can disrupt this ritual, not only will we put off any impending attacks, we can deal a huge blow to their morale! So get in there, rough them up, and make as much of a mess as possible!", sourceObjective = "Throw 8 Kunzen Ritual Candles, kick 4 Blazing Embers, and slay 1 Kunzen Ritualist.", completion = "Hah! They'll be cleaning that mess up for days.", sourceObjectiveStatus = "unverified-source-field" }
quests[30326] = { id = 30326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kunzen Legend-Chief", description = "I've heard people talk about the hozen like they're just some tribe of barely-functional idiots... but that's not true! They have brains, too - they just don't all like to use them that much.\n\nI've heard that the Kunzen tribe has two chiefs - one in charge of fighting, and one in charge of stories, lore, and history.\n\nWhat I wouldn't give to see what kind of stories they tell...", sourceObjective = "Obtain a Kunzen Legend-Book from a Kunzen Legend-Chief.", progress = "I'll bet hozen legends aren't that much different than our own.", completion = "Wow! Look at this! It's...\n\n<Fish flips through the pages, and her face sours.>\n\nOh, I think that's a dirty picture. But the rest of this is very interesting! I just love learning how other creatures think. Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30327] = { id = 30327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Have to Burn the Ropes", description = "I, umm... well...\n\nOh, never mind. It was a stupid idea.\n\nIt's just that, I was thinking that maybe we can stop the Kunzen hozen from attacking us without having to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I think they're using them to climb down to our farms and...\n\nNo, forget it. It was a silly idea anyways.", sourceObjective = "Burn 6 Kunzen Ropes.", progress = "Never mind. I would never ask you to... to do something for plain old me.", completion = "<Ella's face lights up.>\n\nYou did it? For me? Oh, thank you, thank you, thank you, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[30328] = { id = 30328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thousand-Year Dumpling", description = "One of my most popular recipes is the Thousand-Year Dumpling, which is filled with preserved vegetables.\n\nI normally let the vegetables ferment in a hole underneath my house, but when I looked for them this morning, they were gone!\n\nI blame those thieving virmen.\n\nBring them back, and I'll let you help me cook!", sourceObjective = "Obtain 7 jars of Preserved Vegetables.", progress = "Try not to open any of the jars. If you do open one, you might not want to smell it too closely.", completion = "Now, my student, lean in closely. Let me show you the secret of the Thousand-Year Dumpling...", sourceObjectiveStatus = "unverified-source-field" }
quests[30329] = { id = 30329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cindergut Peppers", description = "A certain few pandaren around here prefer their dishes unbearably spicy. Unfortunately, my access to such peppers is limited.\n\nThe Kunzen hozen, in the mountains to the west, often carry cindergut peppers. A few of those and I'll be set for a few days.\n\nSay, could you collect some for me? You might want to wear gloves if you'll be handling them directly.", sourceObjective = "Obtain 4 Cindergut Peppers.", progress = "Just put the peppers down on the cutting board, here. I'd prefer not to touch them myself.", completion = "I don't know how the hozen manage to carry these things on their bodies... let alone eat the things.", sourceObjectiveStatus = "unverified-source-field" }
quests[30330] = { id = 30330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truffle Shuffle", description = "I like to bake with truffles... when I can find them. They only grow up on the Skyrange, and in very, very scarce amounts.\n\nThey're a fantastic ingredient, but we can't risk over-farming them. That's why we need to replace what we've taken. Bring me a handful of adult truffles, and plant some of these spores in their place.", sourceObjective = "Obtain 8 Shadelight Truffles, and plant 8 Shadelight Spores.", progress = "We won't need many truffles. They're for flavor only, really.", completion = "These will do nicely.\n\nNow, {name}... stand closer. Let me show you a thing or two about baking...", sourceObjectiveStatus = "unverified-source-field" }
quests[30331] = { id = 30331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mile-High Grub", description = "Have you ever tried Mushan Tail Stew? Chances are, if you have, that it was stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew: you need to cook it at high elevation.\n\nI've already gathered the ingredients. Take this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew over their bonfire.", sourceObjective = "Prepare 20 bowls of Mushan Tail Stew over the bonfire in the Kunzen Village.", progress = "I used to make daily trips into the mountains, just to practice making this stew.\n\nI was younger, then.", completion = "This is fantastic! You are quite the aspiring cook, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30332] = { id = 30332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fatty Goatsteak", description = "You know what? I think I want to grill up some goatsteak today.\n\nNo, not from the puny little shaghorns they keep around here. They don't have nearly enough fat on them.\n\n<The chef pats his voluminous belly.>\n\nYou think I got to this size eating no-fat-havin' goats?\n\nNow, the shaghorns up on the Skyrange, to the west... those'll do just fine.", sourceObjective = "Obtain 4 Fatty Goatsteaks.", progress = "<The chef is busy preparing spices and sauces for his imminent steaks.>", completion = "Good choice of steaks, {name}. You've got a future as a butcher. You probably make a better {class}, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[30333] = { id = 30333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesser of Two Evils", description = "Like any farming community, we have the occasional virmen troubles.\n\nThe most powerful Springtail virmen live high up in the cliffs to the north, and only come down when they run out of veggies to nibble on.\n\nFrankly, I've dealt with virmen before. They're nothing but a pest that must be kept in check, and there's no better way to do that than by killing their warren-mother. Easy as that.", sourceObjective = "Slay the Springtail Warren-Mother.", progress = "I've had plenty of experience with virmen in the past. Just show them you're stronger than they are, and they'll back off.", completion = "There, that's done with. Now we shift our focus back to farming, for a change.", sourceObjectiveStatus = "unverified-source-field" }
quests[30334] = { id = 30334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing is Bad... Re-Stealing is OK", description = "The hozen, up in the mountains to the west, continue to steal vegetables from my fellow farmers. Being so close to Halfhill, I very rarely suffer hozen attacks, but my friends have not been so lucky.\n\nSeems to me like they steal way more than they can eat. If you can find any intact vegetables up there in those mountains... steal them back!", sourceObjective = "Re-steal 16 Stolen Vegetables.", progress = "Have you got them?", completion = "Thanks! I'll make sure these are distributed out to my fellow farmers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30335] = { id = 30335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalling the Ravage", description = "The Kunzen hozen, up in the mountains to the west, have been acting up, lighting their fires and shouting their chants. Based on what I've heard and seen around here, that means that a ravage is coming.\n\nThere's not much we can do to stop the ravage, but we can at least thin their numbers before they attack.", sourceObjective = "Slay 12 Kunzen Hozen.", progress = "The ravage could come any time now. We have to be prepared.", completion = "They'll be attacking, but my farm - and the farms of my friends - should not be in any danger.\n\nNot if we can help it, anyways. Right, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[30336] = { id = 30336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kunzen Hunter-Chief", description = "From what I've gathered, the Kunzen hozen have two chiefs. One is harmless - he deals with potions, medicines, and ancient fables. The other one is in charge of the Kunzen's hunters - and the only thing they've been hunting lately is our crops.\n\nThe Hunter-Chief is a problem waiting to be solved. I'm sure the local farmers would be grateful if you went up there and, you know, \"took care\" of him.", sourceObjective = "Slay the Kunzen Hunter-Chief.", progress = "Mm-hmm.", completion = "No doubt the hozen will have a big ritual tonight, promoting a new Hunter-Chief.\n\nI'm just happy that my fellow farmers can rest easy in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[30337] = { id = 30337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simian Sabotage", description = "The hozen steal from us, and we keep stealing our stuff back. It has to stop sometime.\n\n<Farmer Yoon hands you a barrel of fireworks.>\n\nFind some of our stolen supplies in their mountain camp to the west, and place these fireworks beside them. Hopefully, if they see the explosions, they'll think our supplies are defective and stop stealing altogether.\n\nIt's worth a shot, right?", sourceObjective = "Use the Barrel of Fireworks near the Pile of Stolen Weapons, the Pile of Stolen Tools, the Pile of Stolen Beer, and the Pile of Stolen Grain.", progress = "Good luck up there, {name}.", completion = "Hopefully they're put off from stealing any more of our supplies. I know I personally wouldn't want to drink any explosive beer, or use an explosive rake.", sourceObjectiveStatus = "unverified-source-field" }
quests[30338] = { id = 30338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weighty Task", description = "For the life of me, I can't figure out why the mogu would have built all their statues and such down in that lake. I'm sure there wasn't always water down there, but it still seems wickedly inconvenient should it ever have rained.\n\nAh well, who's to fathom the strange intentions of the mogu...\n\nWould you be so kind as to swim down there and bring back any artifacts that seem even vaguely carry-able? I'd certainly appreciate it.", sourceObjective = "Recover 8 Mogu Artifacts.", progress = "Have you find a pretty stone thing or two for me? I have a hug waiting for you should you have been so kind!", completion = "Well look at you! Not only can you swim in all that very ornate and heavy-looking gear, you can carry half-a-dozen awkwardly large gilded weapons while you do it! Of all your feats, this is surely one of the most impressive, no?\n\nThank you, you marvelously adept swimmer you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30339] = { id = 30339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting your Hands Dirty", description = "Some of the best fishin' in all of pandaria in this lake right here. I brought enough brew to last me all day, but I didn't think to bring any bait.\n\nWho can really remember such things?\n\nIf you'd be willing to gather me some bait along the shore, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", sourceObjective = "Gather 12 Fresh Whitepetal Worms.", progress = "So much fishin' in store! I can hardly wait to start my waitin'.", completion = "I like a {race} who isn't too lofty to help a humble merchant out. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30340] = { id = 30340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stick in the Mud", description = "I came out for a beautiful day of fishin', but I didn't think to bring a pole. There are so many things to remember for fishin', I just can't keep it all in my head.\n\nThose reeds along the river look alright for makin' a pole out of. If you'd gather me some number of them, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", sourceObjective = "Gather 12 Whitepetal Reeds.", progress = "So much fishin' in store! I can hardly wait to start my waitin'.", completion = "I like a {race} who isn't too lofty to help a humble merchant out. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30341] = { id = 30341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Watchful Eyes", description = "<He looks down at the dead mogu scout at his feet, looks up at you, then points out out down the lake shore. It seems he wants you to find and kill more of these mogu scouts.>", sourceObjective = "Kill 8 Shao-Tien Surveyors.", progress = "<He stares at you blankly.>", completion = "<He bows thankfully.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30342] = { id = 30342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Tongue, Fragile Feet", description = "I was kicking the water for fun again when one of those vicious crocolisks lunged out to try to bite my foot off! Rude! I have proceeded to rest my weary soles a few feet farther from the water, but I already look back on my water-kicking days longingly.\n\nWould you be so kind as to kill a crocolisk or eight for me? I assure you they deserve it for frightening me though.", sourceObjective = "Kill 6 Stillwater Crocolisks.", progress = "I sense them looming below the surface, carefully planning their next assault on one of my appendages. No manner of glaring at them from a distance is dissuading them, so I really do need you to continue with our previously discussed slightly-more-violent plan, if you wouldn't mind.", completion = "Do you hear that, my beautiful feet? You can rest easy now, your water-kicking days have returned!\n\nYou've been oh so lovely, friend. Do share the fruits of your labors and spend a second or two by the water with me someday. We can exchange tales of that one time when you so generously slaughtered a ravaging band of vicious limb-snatching reptiles for the sake of my frightened and innocent feet. What a grand day that was.", sourceObjectiveStatus = "unverified-source-field" }
quests[30343] = { id = 30343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Waterline!", description = "This is Sky-Reaver Stormhowl, captain of the airship Fist of Garrosh and commander of this operation.\n\nYour first task is to burn the 7th Fleet to the waterline while it's still at anchor\n\nCaptain Drok's marines will hold the harbor entrance while your team works.\n\nRig powder barrels in the hold of every ship and then regroup at the harbor entrance to inform Blastmaster Sparkfuse, who will trigger the exposives and signal the airship forward.", sourceObjective = "Rig powder barrels in the hold of all six ships.", sourceObjectiveStatus = "unverified-source-field" }
quests[30344] = { id = 30344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Dynasty", description = "I wonder if I could bother you for another task. My daughter, the good Sentinel Commander Lyalia here, refuses to let me go into the field.\n\nI have spent everyday in that oubliette staring at the ruins to our north, itching to investigate.\n\nIf we are where I suspect we are those ruins could contain the key we need to finding the fabled Pools of Youth!\n\nPlease, {class}! Go to those ruins and salvage any tablets that still have writing on them.", sourceObjective = "Obtain 6 Dynastic Tablets.", progress = "It is one thing to research the lost dynasties. It is quite another to visit their ancient ruins.\n\nI am giddy as I have not felt in centuries!", completion = "Oh! Fabulous! Fabulous!\n\nYour one trip has advanced my research more than ten years of reading dusty tomes and decaying scrolls...\n\nAnd those \"mogu\" you saw. I have been doing some research as well as speaking to Kang on the subject.\n\nI suspect now that they were the race of the lost dynasties that my research is derived from.\n\nOf course, that also means that they are the ones who used to control the Pools of Youth.", sourceObjectiveStatus = "unverified-source-field" }
quests[30346] = { id = 30346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where are the Pools", description = "Perhaps these mogu know where the pools are.\n\nOur scouts have reported seeing a commander along the southern side of the Ruins of Dojan.\n\nKill him and take whatever information he is carrying. They should lead you to the pool.", sourceObjective = "Obtain the Dojani Orders.", progress = "<You sense the presence of Lorekeeper Vaeldrin, then hear his voice within your mind.>\n\nHmm. I'm still not sure about these references to \"torture\" regarding the Pools of Youth.", completion = "Well done, {name}. Hmm, it looks like the mogu are here to collect ancient relics and weapons from their forgotten dynasty. That is a problem we can face later though.\n\nAh! Here is a reference to the Pools of Youth.", sourceObjectiveStatus = "unverified-source-field" }
quests[30347] = { id = 30347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pools of Youth", description = "North! Go north to the Pools of Youth. Get some of the water but be on your guard.\n\nThe mogu list this as a \"high value\" target. Kang Bramblestaff will meet you there if he has not already arrived by your side.", sourceObjective = "Obtain some of the Water of Youth.", progress = "Nothing like being mortal to give one a sense of urgency.", completion = "You... you found the pools! The waters do exist!\n\nSomething is wrong though. I feel equal parts shadow and light swirling in this vial.", sourceObjectiveStatus = "unverified-source-field" }
quests[30348] = { id = 30348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immortality?", description = "Something is... off. The water feels strange.\n\nWhen we arrived here I felt the presence of the Light, strong and vibrant, far to the north.\n\nI thought it would be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu magics.\n\nI think it best I try only a sip and we see what happens.", sourceObjective = "Observe Vaeldrin as he tests the water of youth.", completion = "Wha... what happened? The water... it... it only transfers life. It will not make new life.", sourceObjectiveStatus = "unverified-source-field" }
quests[30349] = { id = 30349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from Dojan", description = "While you were at the ruins dusting off tablets for my father I lost five scouts to wandering mogu patrols.\n\nThese creatures apparently have little interest in peace and are about as trustworthy as the Horde.\n\nThey are too numerous and we are too weak, however.\n\nGo to the ruins west of here and cull the mogu numbers. They won't be expecting a {class}.", sourceObjective = "Kill 6 Dojani Reclaimers, 8 Dojani Surveyors, and 4 Dojani Enforcers.", completion = "Well done, {name}. Another few missions like that and we might have to make you an honorary sentinel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30350] = { id = 30350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squirmy Delight", sourceObjective = "Gather 5 Intact Skitterer Glands.", progress = "Mama Bramblestaff always said Squirmy Delight will cure any hunger one way or another.", completion = "Ha! With this I can make a stew potent enough to knock these waifish elves on their feet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30351] = { id = 30351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lotus Tea", description = "The mogu really like their poisons and curses. Mama Bramblestaff always said lotus tea cures any mogu curse.\n\nI saw some imperial lotus plants in the nearby Ruins of Dojan. We should go gather some of their leaves and keep them on hand just in case the mogu get unruly.\n\nAlso, this will give me a chance to introduce my fists to some mogu faces.", sourceObjective = "Gather 20 Imperial Lotus Leaves.", progress = "I have never seen the mogu this numerous before. They have always been a nuisance but never this bad.", completion = "That's it! You pick, I punch!", sourceObjectiveStatus = "unverified-source-field" }
quests[30352] = { id = 30352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crane Mastery", description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you to go kill me some carp hunters? You'll find them up and down the river west of here. There are a bunch of them so don't hesitate to hunt while doing other stuff.", sourceObjective = "Kill 12 Carp Hunters.", completion = "Fantastic. Only thing that would make this hunting trip more entertaining is a chair. Here is the reward I promised you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30353] = { id = 30353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit Mastery", description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff.\n\nAnd this jungle is just full of tigers. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.", sourceObjective = "Obtain 12 Vials of Tiger Blood.", progress = "I like hunting with Nesingwary and all but he's in it for the hunting. I'm in it for the profit, and he doesn't pay us.", completion = "Great! This stuff is gonna make me a mint back in Kalimdor. Here's your cut.", sourceObjectiveStatus = "unverified-source-field" }
quests[30354] = { id = 30354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Sister Left Behind", sourceObjective = "Rescue 8 captives of the mogu.", completion = "There are so few of us, it is a great relief to see such help.", sourceObjectiveStatus = "unverified-source-field" }
quests[30355] = { id = 30355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Reclaim", sourceObjective = "Recover 10 Mogu Artifacts.", progress = "Every artifact in our possession is one less weapon in mogu hands.", completion = "Well done {name}. You have removed the sword from the child's hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[30356] = { id = 30356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sever Their Supply Line", description = "The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing in reinforcements and supplies.\n\nWhat is worse, they are sending their captives through these portals.\n\nGo to the Ruins of Korja and destroy as many of these Korjan Reclaimers as you can find.", sourceObjective = "Kill 8 Korjan Reclaimers.", completion = "You have bought us some much needed breathing room to lick our wounds and prepare a counter-attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[30357] = { id = 30357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stoneplow Convoy", sourceObjective = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys.", progress = "These mantid are a much bigger threat than I think even the pandaren give them credit for.", completion = "It has been a long time since I rolled up my sleeves and helped the needy. In my lust for immortality I forgot why I became a priest.\n\nThank you for reminding me there is good in this world worth fighting for, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30359] = { id = 30359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord Reclaimer", sourceObjective = "Find Lyalia and kill Groundbreaker Brojai.", progress = "Lyalia is the only family I have left. I had to bury her mother during the war of Ahn'Qiraj.", completion = "Thank you for avenging my daughter. I am not willing to let her stay dead however.\n\nI still have the waters of youth.", sourceObjectiveStatus = "unverified-source-field" }
quests[30360] = { id = 30360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Stoneplow", description = "My father gave me his life. Tyrande gave me her trust. My sentinels gave me their allegiance.\n\nIt is time I repaid them all.\n\nWith Brojai dead we can mop up the remaining mogu. The next threat is the mantid.\n\nGo north to Stoneplow and lend them your help. Tell them I will be bringing what sentinels I can muster to aid in the defense of their city against the mantid.", sourceObjective = "Travel to Stoneplow Village in Valley of the Four Winds.", completion = "Mantid from the south? This is not a good day.", sourceObjectiveStatus = "unverified-source-field" }
quests[30361] = { id = 30361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", sourceObjective = "Kill 10 Ik'thik Mantid.", progress = "It has been many thousands of years since mantid were seen on this side of the Great Wall.", completion = "Thank you for your help, {class}! I've never seen anybody stand up to the mantid like that before.\n\nWell, other than the Shado-Pan, of course...", sourceObjectiveStatus = "unverified-source-field" }
quests[30363] = { id = 30363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nI want you to look for my scout. I sent her to investigate the Crane Temple but she hasn't returned.\n\nGet her report and rendezvous with us at the Sentinel Basecamp further west.", sourceObjective = "Get Incursion Sentinel's Report.", progress = "Did you find the scout?", completion = "{name}, well timed as usual. It turns out the mogu know how to use portals as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[30376] = { id = 30376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Springs Eternal", sourceObjective = "Speak with Loon Mai in Stoneplow.", completion = "Finally, some good news. I will send a falcon to Winter's Blossom right away and let them know the Temple of the Red Crane is safe.\n\nBetween the sha outbreak and the increasing aggression of the mantid, our forces are being stretched thin.", sourceObjectiveStatus = "unverified-source-field" }
quests[30379] = { id = 30379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Gina", progress = "Don't just stand there gawking. Spit it out.", completion = "Oh my, this is a flawless jewel!\n\nIf you keep giving me gifts like these, I may have to retire early!" }
quests[30380] = { id = 30380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Gina", progress = "It's busy at the market today. What can I do for you?", completion = "Oh, what a lovely apple! These sweet fruits are quite the treat around here." }
quests[30381] = { id = 30381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Ella", progress = "Do you have any pets? I like cats, but dogs are nice, too.", completion = "Oh, a jade cat!\n\nMy father and I used to hunt for these in the fields. He always said they were lucky." }
quests[30382] = { id = 30382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Ella", progress = "It's a lovely day out, don't you think?", completion = "Oh, thank you. This beautiful feather is just lovely." }
quests[30383] = { id = 30383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Ella", progress = "Hmm? Oh hello. How are you today?", completion = "Oh my, these are quite rare. Thank you for giving it to me." }
quests[30384] = { id = 30384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Them!", description = "Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not long before you arrived.\n\nI don't know how he got here but I can guarantee you he isn't alone. They never are.\n\nKill the sunwalker scout before he reports our position.", sourceObjective = "Kill the Sunwalker Scout.", completion = "Sunwalkers are not to be trusted. They are the most militant branch of the tauren armies within the horde.\n\nThank you for your help in this, {name}. Please accept this token as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[30385] = { id = 30385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "I offer you my heartfelt appreciation for your aid. Anji awaits you in the Setting Sun Garrison to the west.\n\nMay the day favor you, young {class}.", sourceObjective = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "Welcome. Che send you?", sourceObjectiveStatus = "unverified-source-field" }
quests[30386] = { id = 30386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Ella", progress = "A good day to you, neighbor.", completion = "Oh my, Shrimp Dumplings? My favorite!\n\nThank you." }
quests[30387] = { id = 30387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Gina", progress = "Better to have many customers than none at all. How can I help you?", completion = "What an interesting little figurine. It's quite lovely. Thank you, dear." }
quests[30388] = { id = 30388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Gina", progress = "What have you got there, neighbor?", completion = "Such a pretty feather would fetch a nice price at market, but I'm not selling this one. Thank you for the gift." }
quests[30389] = { id = 30389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Gina", progress = "Hello {name}. Are you getting to know everyone in town?", completion = "Oh wonderful! You've brought me a Marsh Lily.\n\nHow did you know that these are my favorite?" }
quests[30390] = { id = 30390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Gina", progress = "I've been on my feet all day. You'd be surprised how busy this place gets.", completion = "Bringing food to me on the busiest market day? What a sweetheart you are!" }
quests[30391] = { id = 30391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Old Hillpaw", progress = "I got my own share of troubles at my farm. I don't need any of yours.", completion = "Oh, for me? Well, I guess that's mighty nice of you." }
quests[30392] = { id = 30392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Old Hillpaw", progress = "Dang monkeys been at my farm again. Sure puts me in a foul mood.", completion = "Well ain't that sweet of ya. Hmph." }
quests[30393] = { id = 30393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Old Hillpaw", progress = "Whaddaya want today, {race}?", completion = "Hmph, well that is mighty fine of you to think of me like that.\n\nThank ye." }
quests[30394] = { id = 30394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Old Hillpaw", progress = "Can't an old man get some peace and quiet around here?", completion = "...\n\nMy son, Tai...he used to collect these as a little boy.\n\nWhen his mother died, I told him they were messages from her, fallen from the heavens.\n\n<Old Hillpaw falls into a grim silence.>" }
quests[30395] = { id = 30395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Old Hillpaw", progress = "Got a harvest coming up and my back's been giving me trouble again. Oh well, we all have to make do around here.", completion = "Oh, these flowers are quite rare.\n\nYou know that these are considered lucky? Maybe my harvest will go well after all. Thank you." }
quests[30396] = { id = 30396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Old Hillpaw", progress = "My wife used to make the most delicious braised turtle in four counties! I miss that woman.", completion = "I haven't had this dish since my wife died. Somehow, she must have sent you to me.\n\nThank you, {race}." }
quests[30397] = { id = 30397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Chee Chee", progress = "What you want?", completion = "Pretty stone! You silly for giving away. Oh well, mine now!\n\nThanks, {race}!" }
quests[30398] = { id = 30398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Chee Chee", progress = "Me not same as mountain monkeys. You get that straight.", completion = "For me? Red apple? So shiny! So juicy! Thanks, boss!" }
quests[30399] = { id = 30399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Chee Chee", progress = "Chee Chee was first hozen Tiller. If I could do it, so could you.", completion = "Ooh, very old, very valuable. Me like kitties. Got one from girl Ella." }
quests[30400] = { id = 30400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Chee Chee", progress = "Ookin' mountain hozen! They not know how hard little Chee Chee workin'. Bad monkeys!", completion = "Oh my. You know what this is? A frikfrak! Frikfrak for chief only!\n\nWhich mean...you must think me is chief? We boss buddy now, {name}." }
quests[30401] = { id = 30401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Chee Chee", progress = "Little Chee Chee lived here all my life. This is my home.", completion = "Oh! Pretty flower! No takebacks boss, okay? Thank you, bye!" }
quests[30402] = { id = 30402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Chee Chee", progress = "Chee Chee work in fields all day, so tired!", completion = "Oh, Valley Stir Fry. Thanks!" }
quests[30403] = { id = 30403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Sho", progress = "Yes, {class}. What can I do for you?", completion = "For me? Why thank you." }
quests[30404] = { id = 30404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Sho", progress = "Shhh, listen. Always be on the alert.", completion = "Thank you." }
quests[30405] = { id = 30405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Sho", progress = "The first step to disciplining your mind is to discipline your body.", completion = "I appreciate the sentiment, {race}." }
quests[30406] = { id = 30406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Sho", progress = "The watch is never finished.", completion = "I appreciate your gesture, {race}. Thank you for thinking of me." }
quests[30407] = { id = 30407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Sho", progress = "I have been hard at work, eliminating hozen up on the mountain.", completion = "I have never been one to dwell on pretty, useless things, but I know you give me this gift out of friendship. For that, I thank you. Whenever I look at this flower, I will think of you." }
quests[30408] = { id = 30408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Sho", progress = "Do not let your strength waver.", completion = "Ah, this is the best gift you could have given me! A warrior needs her strength." }
quests[30409] = { id = 30409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Haohan", progress = "Have you ever been to the Tiller's Union building in Halfhill?", completion = "Oh yes, this ruby will go nicely with the rest of my collection." }
quests[30410] = { id = 30410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Haohan", progress = "How are things going at the farm?", completion = "Mmm, I do like a lovely apple." }
quests[30411] = { id = 30411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Haohan", progress = "What is it? I'm a busy man.", completion = "Oh, this is exquisite craftsmanship. Where did you find such a thing?" }
quests[30412] = { id = 30412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Haohan", progress = "Howdy, {race}.", completion = "Hmm, this is a very lustrous feather. I'll add it to my collection of rare things." }
quests[30413] = { id = 30413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Haohan", progress = "A good farmer keeps his soil tilled for planting. Untilled soil ain't no good for nobody, right {name}?", completion = "Hmm, I guess these flowers are supposed to be pretty lucky. I'm honored that yer giving it to me." }
quests[30414] = { id = 30414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Haohan", progress = "A good farmer knows when to work and when to eat! You have to enjoy the fruits of your labor, right?", completion = "Charbroiled Tiger Steak for me? How did you know this was my favorite dish?" }
quests[30416] = { id = 30416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Farmer Fung", progress = "Hey, it's the citypaw!", completion = "Oh, that's a very nice stone." }
quests[30417] = { id = 30417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Farmer Fung", progress = "How are you, {race}?", completion = "Such a nice red apple for me?" }
quests[30418] = { id = 30418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Farmer Fung", progress = "What can I do for you?", completion = "Hmmm, a very interesting little statue." }
