quests[30431] = { id = 30431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Tina", progress = "Would you like to sit down for a bit, {race}?", completion = "Oh, this blue feather will really bring out my eyes. Thank you, {name}." }
