quests[30433] = { id = 30433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Tina", progress = "Please say hello to Farmer Yoon for me.", completion = "Oh this is my favorite dish! Yum!" }
quests[30434] = { id = 30434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Jogu", progress = "Spare a copper for a drink?", completion = "Oh, a pretty stone! I will look at this while I'm drinking." }
quests[30435] = { id = 30435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Jogu", progress = "Buy a jinyu a drink?", completion = "Hey, this is my favorite food! Thanks, {name}." }
quests[30436] = { id = 30436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Jogu", progress = "It's hard work you know, interpreting all these visions.", completion = "Thanks." }
quests[30437] = { id = 30437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Jogu", progress = "Tomorrow's crop will be... oh, I can't see it yet. I need something to drink, first.", completion = "A nice blue feather for me? Thanks, {race}." }
quests[30438] = { id = 30438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Jogu", progress = "The watersh shay that I will have great fortune today.", completion = "The watersh were right! Thish flower will bring me luck." }
quests[30439] = { id = 30439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Jogu", progress = "You know what goes with a good drink? A good meal.", completion = "Nothing like a delicious cold brew, and some Sauteed Carrots to wash it down." }
quests[30442] = { id = 30442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blanche's Boomer Brew", description = "Brew Blanche's Boomer Brew by Protecting the Brewkegs.", sourceObjective = "Help create the Boomer Brew. If the Brewkegs catch on fire, fix them!", sourceObjectiveStatus = "unverified-source-field" }
quests[30444] = { id = 30444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Reprieve", description = "We've been granted a brief respite from the mogu attacks as they attempt to recoup near the Five Sisters to our north. I would like you to see to it that they not be granted a similar reprieve.\n\nShow no mercy.", sourceObjective = "Kill 8 Shao-Tien mogu near the Five Sisters.", progress = "These mogu are like roaches. It seems near impossible to do away with them for good.", completion = "That should keep them off balance for a while. Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[30445] = { id = 30445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waters of Youth", sourceObjective = "Give Vaeldrin's message to Lyalia.", completion = "He... he shouldn't have done that! He shouldn't have paid for my mistake!", sourceObjectiveStatus = "unverified-source-field" }
quests[30449] = { id = 30449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Crane Deck", description = "Now that you have gathered all of the Crane cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Crane Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Crane deck!   Congratulations!", completion = "So you have put together a Crane deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[30450] = { id = 30450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Ox Deck", description = "Now that you have gathered all of the Ox cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Ox Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Ox deck!   Congratulations!", completion = "So you have put together a Ox deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[30451] = { id = 30451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Serpent Deck", description = "Now that you have gathered all of the Serpent cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Serpent Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Serpent deck!   Congratulations!", completion = "So you have put together a Serpent deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[30452] = { id = 30452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Tiger Deck", description = "Now that you have gathered all of the Tiger cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Tiger Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Tiger deck!   Congratulations!", completion = "So you have put together a Tiger deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[30457] = { id = 30457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call Out Their Leader", description = "Clearly, you are a hero come to aid us.\n\nSlay the Bataari Tribe in the Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to appear.  Dispatch him.", sourceObjective = "Slay 10 Bataari Tribe Members in the Kun-Lai Pass until the Bataari Fire-Warrior appears. Then kill him.", progress = "If the war leader of the yaungol is slain, surely our village will be saved and the refugees will be able to return to their farms.", completion = "We are delivered! I was right about you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30458] = { id = 30458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scouts Return", description = "{name}, your friends have returned from their scouting mission. They need to see you immediately.\n\nI'm afraid...\n\nWell, I'd better say no more. You will see for yourself.", sourceObjective = "Speak to Rell Nightwind at the Glassfin Village in the Jade Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[30459] = { id = 30459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All of the Arrows", description = "As soon as their reinforcements arrive, the yaungol are going to overrun our position here. If they do that, the village will be lost.\n\nWould you be willing to retrieve as many arrows off the battlefield as you can carry? I have a plan that just might save us with your help.", sourceObjective = "Collect 12 Arrows for Commander Hsieh.", progress = "How many arrows do you have?", completion = "Thank you, {name}. You've saved our defensive line here.\n\nThis next attack wouldn't have been possible without you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30460] = { id = 30460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit Medicine", description = "Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to the northwest.\n\nTake this liniment.  It is a powerful medicine that has been passed down in my family over the generations.\n\nUse the dit da jow to heal the injured warriors if you do not have healing powers of your own to use on them.", sourceObjective = "Use the Dit Da Jow or your own healing to aid 8 Injured Binan Warriors.", progress = "There are yet more injured warriors in need of aid, {class}.", completion = "You have my thanks, {name}. You have shown great honor through your actions.\n\nI hope that my family's dit da jow was of some use to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30461] = { id = 30461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", sourceObjective = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", completion = "I see... So the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Bastion, I have to implore you to help us deal with them here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30462] = { id = 30462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds rests the  Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", sourceObjective = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", completion = "I see... So the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Bastion, I have to implore you to help us deal with them here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30464] = { id = 30464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going West", description = "Leza now walks with the ancestors of this strange land. I must look now to the living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nTrack him down and lend what aid you can to him. We will join you as quickly as we are able.", sourceObjective = "Travel to Dawnchaser Retreat.", completion = "{name}! Well timed!\n\nWe were laying an ambush for the Alliance in the ruins west of here when the mogu ambushed us. They are using mage portals to call in reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[30465] = { id = 30465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nWe are pressing westward and could use your help.\n\nMeet us at the Sentinel Basecamp further west when you are ready.", sourceObjective = "Speak with Lyalia at the Sentinel Basecamp in the Krasarang Wilds.", completion = "{name}, well timed as usual. It turns out the mogu know how to use portals as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[30466] = { id = 30466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sufficient Motivation", description = "Training these savages has been quite a task, {name}.\n\nFinding ways to motivate them was easy enough; the problem is keeping them motivated.. and focused... and awake.\n\nNow that you're back, you can help me in getting the less disciplined Hozen moving, if you catch my drift. I'll leave the method up to you.", sourceObjective = "Motivate 10 Lazy Hozen.", progress = "Are the Hozen ready to deploy?", completion = "Hrmm, I'll be surprised if we can keep these creatures focused enough to employ any tactics at all, {name}.\n\nThey'd better not get in my way when blades begin to fly!", sourceObjectiveStatus = "unverified-source-field" }
quests[30467] = { id = 30467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Son...", description = "My son - can you find my son?\n\nWhen the Jinyu attacked, he ran off in the confusion. I don't know if they've done anything with him, or if he's still alive, even.\n\nNothing else matters if I can't find him. \n\nI'd ask Mei... but something's wrong with her. She seems too... impulsive since the attack. I just can't trust that she'd bring him back safely.", sourceObjective = "Find Wu-Peng in the Inkgill Mere.", completion = "So horrible... When I saw the killing, I just ran. My father, Mei... are they alive?", sourceObjectiveStatus = "unverified-source-field" }
quests[30468] = { id = 30468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Vengeance", description = "<The Swordmistress does not look well. There's a darkness to her eyes uncharacteristic of the pandaren.>\n\nI don't think I've ever been as... as furious as now. What betrayal!\n\nI fought them off when they attacked, killed a few here, but Merchant Shi is too much of a coward to let me go and finish the job!\n\nYou, do it for me. Kill them. Kill them all.", sourceObjective = "Kill 15 Enraged Jinyu.", progress = "Are they dead?", completion = "It is satisfying to hear that our enemies are dead. Perhaps you can use one of my bodyguard's weapons.", sourceObjectiveStatus = "unverified-source-field" }
quests[30469] = { id = 30469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repossession", description = "Of course, the first priority is finding my son. But, if we save ourselves only to starve, then what have we accomplished, in the end?\n\nPlease, I need you to recover some of the supplies that the Jinyu took from our caravan.", sourceObjective = "Collect 8 Stolen Supplies.", progress = "Have you found the supplies?", completion = "Thank you... we will eat now, at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[30470] = { id = 30470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Tina", description = "That Tina Mudclaw is in the Halfhill Market today, visiting her sister. She's really nice, but she's really hard to get gifts for!\n\nThere's a little jewel that can be found in the cliffs to the north. It's called a chrysoberyl, and it changes color when you hold it. I'll bet she doesn't have one of THOSE!\n\nLook inside the virmen caves. I bet you'll find one really fast.", sourceObjective = "Obtain an Uncut Chrysoberyl.", progress = "Hey there, {name}! Nice to see you again.", completion = "<Tina holds the gem in her hands, and watches it change from a pale blue to a bright red.>\n\nA chrysoberyl? That's so sweet! Was this Andi's idea?\n\nOf course I already have several... but this one is beautiful, too. I'll add it to the collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[30471] = { id = 30471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Chee Chee", description = "That crazy Chee Chee is actually pretty neat. Mah always said that hozen were nothing but trouble, but... I guess he's just a better hozen then the rest of them.\n\nWe should do something nice for him! Those mountain hozen in the west make some really fancy stir fry, and keep bowls of it inside their little hozen houses.\n\nI bet Chee Chee would love some!", sourceObjective = "Obtain an Authentic Valley Stir Fry.", progress = "Mmm?", completion = "For me? Me, Chee Chee?\n\nThis brings Chee Chee back to when Chee Chee was little wikkin' baby. Chee Chee's mama used to make it just like this.", sourceObjectiveStatus = "unverified-source-field" }
quests[30472] = { id = 30472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Sho", description = "Sho - that girl who lives up in the mountains - is in town today. I saw her walking toward the Halfhill Market.\n\nSuch a long walk... she must be hungry! And I think I know just the thing that she'll like.\n\nThe hozen up on the Skyrange cook a soup out of fish and apples. It sounds gross, I know... but it's awesome. You'll find it near their big, scary totem.", sourceObjective = "Obtain a bowl of Yu-Ping Soup.", progress = "Oh! Hello, {name}.", completion = "I was famished! How'd you know? Who told you?\n\nAndi, huh? That kid's gonna grow up to be a real heartbreaker someday...", sourceObjectiveStatus = "unverified-source-field" }
quests[30473] = { id = 30473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fish", description = "That Fish Fellreed is kind of weird. First of all, her name's Fish. That's weird.\n\nOnce you talk to her, though, she's really a nice lady. Did you know that she's an animal lover?\n\nI've got an idea! The Kunzen hozen, in the mountains to the west, make little animal statues and put them in their huts to scare off bad guys. I bet Fish would LOVE something weird like that!", sourceObjective = "Obtain a Yak Statuette from the inside of a Kunzen hozen hut.", progress = "Hey, {name}! What's up?", completion = "Aww, look at him! He's ADORABLE! With his fuzzy little tail, and his...\n\n<She composes herself.>\n\nI mean, ah... thanks, dude. It's pretty cool.", sourceObjectiveStatus = "unverified-source-field" }
quests[30474] = { id = 30474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Ella", description = "That poor Ella. She's so shy! I saw her standing in the Halfhill Market, looking really hungry, but afraid to talk to any of the chefs.\n\nWe should bring her some food! And not any boring food - something special.\n\nThe Kunzen hozen make spicy shrimp dumplings from ingredients they've stolen from our farms. I don't like spicy food, but Ella might!", sourceObjective = "Obtain Spicy Shrimp Dumplings.", progress = "Oh, umm... hi.", completion = "You didn't have to do this! I didn't need any... any...\n\n<Ella eyes the dumplings, and her mouth begins to water.>\n\nWell, maybe I was a little hungry. Thanks, {name}. And give my thanks to Andi, as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[30475] = { id = 30475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fung", description = "Farmer Fung is pretty mean, and just a little scary. Mah always said that he was one of the best farmers in the valley, though.\n\nI think I know the perfect gift for a mean, kind of scary guy like him.\n\nThere's some big plainshawks that circle the hills to the west of here. You should get one, find a big piece of meat, and then ask Kol Ironpaw to grill it up!", sourceObjective = "Obtain a Bloody Plainshawk Leg from a Monstrous Plainshawk, and then bring it to Kol Ironpaw in the Halfhill Market.", progress = "Harrumph!", completion = "Hey! Where'd you get that? I thought they were out of plainshawk!\n\nAndi asked you to get this for me? Huh. Maybe I underestimated that kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[30476] = { id = 30476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Old Hillpaw", description = "Old Hillpaw has about a million chickens on his farm... but that's not what he REALLY loves.\n\nI saw. He collects blue feathers.\n\nI don't realy know where to get a blue feather around here, but I do know where to find some blue pearls!\n\nCheck the oysters in Cattail Lake to the northwest. I'm sure a blue pearl will look nice with his feather collection!", sourceObjective = "Find a Blue Freshwater Pearl.", progress = "{name}! You startled me.", completion = "Well would you look at that! I'll have to keep this somewhere that the chickens can't get to.\n\nDid Andi tell you to get this for me? Funny kid, that one.", sourceObjectiveStatus = "unverified-source-field" }
quests[30477] = { id = 30477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Haohan", description = "Haohan Mudclaw is the big boss of the Tillers union and the richest guy in the Valley! He's been nice to let me stay here, so I want to do something nice for him.\n\nHe likes expensive stuff, like ruby shards, but I don't have a lot of money, so I need to get him something else.\n\nI know! I've seen a great big fish in Cattail Lake! We should get one of its teeth as a gift!", sourceObjective = "Obtain an Enormous Cattail Grouper Tooth.", progress = "Need something, {class}?", completion = "Well, would you look at that! You don't see a tooth like THAT everyday.\n\nYou been hunting sharks, {class}?\n\nThank you, {name}. And send my thanks to Andi, as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[30478] = { id = 30478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Jogu", description = "Sometimes I feel sad for Jogu. He's the only jinyu around, and I don't think he has any friends. Other than his smelly bottle, of course.\n\nYou know what? I've got an idea. Farmer Yoon has a basket of craneberries inside his house, and a few apples as well. I'm sure you could bring them to the stillmaster in the Halfhill Market and get him to brew something special for Jogu.", sourceObjective = "Obtain 8 of Yoon's Apples and 50 of Yoon's Craneberries, then bring them to Bobo Ironpaw to brew into Apple-Berry Hooch.", progress = "Hmm?", completion = "<Jogu takes a long swig from the hooch.>\n\nThat'sh it! I've got a new favorite drink. An' it'sh this one!\n\nYou know what, {name}? You're alright. I mean it, man!", sourceObjectiveStatus = "unverified-source-field" }
quests[30479] = { id = 30479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Gina", description = "Have you seen Gina Mudclaw, the market girl? She has it all - looks, brains, and nice big tummy. Could you deliver a gift for me?\n\nI wanted to pick some orchids that grow on top of the big hills to the west, but I can't climb that high. Could you pick a few and bring them to Gina?\n\nOh, and when you see her... tell her I said \"hi\".", sourceObjective = "Obtain a Goldenfire Orchid.", progress = "Hey there!", completion = "These are beautiful! Did you get these for me?\n\nAhh... so they're from Andi, are they? I think I know somebody who's getting a kiss on the forehead later this afternoon...", sourceObjectiveStatus = "unverified-source-field" }
quests[30480] = { id = 30480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual", description = "From the moment I first rose from the river, I knew I was destined to be Waterspeaker.\n\nI was taught many rituals, and have performed all of them, save one.\n\nThere was one, an extremely ancient one, that we were told to call upon if our people ever turned against us. \n\nThis must have happened in our people's distant past, because we haven't needed to use it in our village's memory.\n\nI suppose now is the time to do so.", sourceObjective = "Speak with Waterspeaker Gorai, and then complete the Ritual.", progress = "That... was not what I expected.", completion = "I see now that this ritual rips whatever was controlling the minds of these creatures from them. I now know what we must do.", sourceObjectiveStatus = "unverified-source-field" }
quests[30481] = { id = 30481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved in Stone", description = "You see the shiny stones in the walls? Rook wants some. The mogu been collecting them, so they have some to take too maybe.\n\nIf you find stones, you please bring them to Rook? Rook will be your friend.", sourceObjective = "Collect 12 Guo-Lai Runestones.", progress = "You find stones for Rook? Please?", completion = "So many!  And so shiny! You did real good!\n\nThank you, little friend. Rook like you a lot.", sourceObjectiveStatus = "unverified-source-field" }
quests[30482] = { id = 30482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul-Gatherer", description = "A single large mogu performing a ritual on the lake caught your attention while you were killing the other mogu in the area. It seems unwise to let his ritual complete.", sourceObjective = "Kill Shadowmaster Sydow and recover the beads from his corpse.", progress = "<He looks at you expectantly.>", completion = "<As you hand the beads to He, his smile suggests that he understands perfectly what they symbolize. He nods approvingly.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30484] = { id = 30484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Our Progress", description = "The time for war is at hand, {name}!\n\nWe've been training these natives non-stop since you left, and I believe they're as good as they're going to get.\n\nSee for yourself. Check in with the others and return with your findings.\n\nWe must rely on our enemy being somehow... even less prepared.", sourceObjective = "Check in with Shademaster Kiryn, Rivett Clutchpop, Shokia, and Riko.", progress = "How is our combat training coming along?", completion = "At least they're confident.\n\nThat might count for something.", sourceObjectiveStatus = "unverified-source-field" }
quests[30485] = { id = 30485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Piece of the Puzzle", description = "These hozen are behaving most unnaturally, {name}. Marching in formation? In armor?\n\nThis troubles me. We must discuss it at another time, however. I have come to ask for your assistance.\n\nThe ancient fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.", sourceObjective = "Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook.\n\nSpeak with Mishi for transportation.", completion = "<Lorewalker Cho shudders, in spite of himself.>\n\nThe legends... they're true!", sourceObjectiveStatus = "unverified-source-field" }
quests[30487] = { id = 30487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Comin' Round the Mountain", description = "The mountain pass is very dangerous. You need much luck to survive. Nephew Bentnail will show you the way.\n\nPerhaps today is a lucky day to travel though. Wind blows from the east; this is good sign. Grummles always travel best when east wind blows.\n\nClimb in the cart when you are ready to leave.", sourceObjective = "Escort the cart and guides safely up Neverest Mountain.", completion = "You've arrived just in time, {class}! I was starting to think I would die up here!", sourceObjectiveStatus = "unverified-source-field" }
quests[30488] = { id = 30488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Muskpaw", description = "What the heck are you supposed to be? A {class}? Never heard of one of them. You here to help or to steal my yaks?\n\nLook, if yer' insistin' on helpin' out, go find my boy. He got himself grabbed by a bunch of sprites and probably doesn't even know we lost the ranch.\n\nThey dragged him off to Pranksters' Hollow south east of here. Go rescue him an' I'll see about giving you a reward of some sort.", sourceObjective = "Find Muskpaw Jr. in Pranksters' Hollow.", completion = "Thank you for the save, stranger!", sourceObjectiveStatus = "unverified-source-field" }
quests[30489] = { id = 30489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Needle Scent", description = "Say, if you really are here to help, I could use me some needles off them sprites in Pranksters' Hollow.\n\nThe grummles don't believe in luck they can't smell. They'll pay better for yaks that have that fresh needle scent.", sourceObjective = "Gather 100 Pungent Sprite Needles.", progress = "Mmm. Nothing like the fresh scent of needle.", completion = "You just earned me a handsome bonus. Getting those needles is a pain in the paw but worth it when we take our yaks to market. Here, for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[30490] = { id = 30490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yakity Yak", description = "Yaungols! They come through here taking what they want and destroying whatever's left.\n\nI can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left.\n\nHead over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.", sourceObjective = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30491] = { id = 30491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the Yak Wash", description = "Look, my father is crazy. I love him, but he's crazy.\n\nThese yaungol managed to completely obliterate our ranch and scattered our yaks every which way.\n\nIf I know my father though, he's going to try to go head to head with the yaungol to get the yaks back.\n\nCan you help us round up some of the yaks so my father doesn't do anything stupid?\n\nJust ride them over to the Yak Wash so we can clean them up and sell them to the grummles.", sourceObjective = "Bring 6 Escaped Yaks to the Wash Entrance at Lao & Son's Yak Wash.", progress = "The grummles always insist they have better luck with cleaned yaks.\n\nAs long as they pay more I'm not going to argue. We need the gold. Now more than ever.", completion = "Well done, stranger! Hopefully we'll be able to cash these in and recoup some of the damages the yaungol inflicted.", sourceObjectiveStatus = "unverified-source-field" }
quests[30492] = { id = 30492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in Yak", description = "I wasn't lying about your reward. Here, take these washed yaks to the grummle caravan master Eightcoins.\n\nYou can find him at the Grummle Bazaar west of here. He'll credit us and give you a delivery fee.\n\nHe may be short, but he is our biggest customer.\n\nReturn to me if you lose the yaks. More often than not they just come right back here anyway. Once they've been cleaned that is.", sourceObjective = "Bring the Washed Yaks to Lucky Eightcoins at the Grummle Bazaar in Kun-Lai Summit. Return to Muskpaw Jr. if you lose your yaks.", completion = "Ah! I can smell the luck from here. The Muskpaws always have good yaks for sale.", sourceObjectiveStatus = "unverified-source-field" }
quests[30495] = { id = 30495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love's Labor", description = "Can I trouble you for another favor?\n\nWe're way behind schedule, and this jade shipment is the last we need to finish the great statue.\n\nI've got my hands full, so could you run this ore over to the other foremen?\n\nHistorian Dinh, Surveyor Sawa, and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is directing production at the top of the statue.\n\nWe're on a deadline, so make sure you do it fast! Time's a wasting!", sourceObjective = "Deliver the jade to Historian Dinh, Surveyor Sawa, Kitemaster Shoku, and Taskmaster Emi.", progress = "Did you deliver the jade in time?", completion = "What, done already? You're quite the runner, {class}. You ever thought about making a living out of this?", sourceObjectiveStatus = "unverified-source-field" }
quests[30496] = { id = 30496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waterspeaker's Staff", description = "There is great dissent in Inkgill, {race}. Elder Shai Hu drank the sha-corrupted waters of the mere, and forced the others to do the same. When I protested, Orachi of the town guard confiscated my ritual staff and banished me.\n\nNow, I am not only an exile, I am unable to speak with the waters that once gave me guidance!\n\nI am not a fighter. But if you are, perhaps you can recover my staff from Orachi? He is in town to our north.", sourceObjective = "Recover Waterspeaker Gorai's Stolen Inkgill Ritual Staff from Orachi in Inkgill Mere.", progress = "Have you found the staff?", completion = "Good. Now we have some hope of redeeming this situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[30498] = { id = 30498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", sourceObjective = "Report to Admiral Taylor in Pearlfin Village.\n\nProvided item:", completion = "Welcome back, {name}. I trust your journey has been insightful, particularly in regards to the layout of the land. There is still much to do before we march into battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[30499] = { id = 30499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", sourceObjective = "Return to General Nazgrim at Grookin Hill.\n\nProvided item:", completion = "Throm-Ka, {name}!\n\nI hope you were able to gather useful information while on your journey through the forest.\n\nOur preperations are almost complete, but your help is needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[30500] = { id = 30500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Residual Fallout", description = "Pandaria is a mystical land, traveler.\n\nIt bears repeating that some of its secrets remain hidden, even to Lorewalkers.\n\nSealing those fissures did not mend what has been broken. If the legends are true, it will take much more to release this land from the grasp of the Sha.\n\nThe aggression of that battle awakened a host of living negative emotions. What you see here is likely the first of many such manifestations.\n\nFor now, we can only try to diminish their presence here.", sourceObjective = "Destroy 10 Sha Echoes", completion = "This is terrible...\n\nWe must find a way to undo what has been done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30501] = { id = 30501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gossip Accept Quest Test Case" }
quests[30502] = { id = 30502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaded Heart", description = "The more powerful remnants of that horrible manifestation may be too much for you to handle on your own, {name}.\n\nI fear I'd be of little help in terms of actual combat, but I can suggest a solution.\n\nThe great jade statue was soon to become a living serpent - one of our revered celestials. Its construction imbued it with special powers that may sufficiently weaken these adversaries.", sourceObjective = "Use Celestial Jade Chunks to defeat 6 Sha Remnants.", progress = "Do you have the jade, {name}?", completion = "<Cho looks at you despondently.>\n\nThis jade was meant for... so much more.", sourceObjectiveStatus = "unverified-source-field" }
quests[30504] = { id = 30504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", sourceObjective = "Use Cho's Fireworks near General Nazgrim, Shademaster Kiryn, Shokia, and Rivett Clutchpop.", completion = "My thoughts will be with your fallen companions, traveler.\n\nMay their wounds mend well.", sourceObjectiveStatus = "unverified-source-field" }
quests[30506] = { id = 30506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", sourceObjective = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", completion = "{name}, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[30507] = { id = 30507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", sourceObjective = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", completion = "{name}, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[30508] = { id = 30508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", sourceObjective = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", completion = "{name}, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[30509] = { id = 30509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", sourceObjective = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", completion = "Where have you been, {name}? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they.", sourceObjectiveStatus = "unverified-source-field" }
quests[30510] = { id = 30510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", sourceObjective = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", completion = "Where have you been, {name}? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they.", sourceObjectiveStatus = "unverified-source-field" }
quests[30511] = { id = 30511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", sourceObjective = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", completion = "Where have you been, {name}? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they.", sourceObjectiveStatus = "unverified-source-field" }
quests[30512] = { id = 30512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westwind Rest", description = "<Admiral Taylor winces in pain.>\n\nJade Forest was a disaster. \n\nAnduin's gone. We lost some good people. We didn't stop the Horde from advancing into the continent. \n\nBut I think I've found a way to get the locals on our side. You just helped fight off some of these \"yaungol\", no?\n\nI hear yaungol sacked Westwind Rest, a local village. We've been told that two groups of survivors have camped out along the road west out of town.\n\nWe help them out, maybe they'll consider siding with the Allliance.", sourceObjective = "Speak with Farmhand Bo and Elder Tsulan in the Yaungol Advance.", progress = "I will not rest until our people are returned and this village rebuilt.", completion = "Well... we are alive, and that is better than we could have hoped for without your help.\n\nBut, if this is truly to become a base of operations for you, and if we are to join your Alliance, there is one more thing you must do to guarantee our security.", sourceObjectiveStatus = "unverified-source-field" }
quests[30513] = { id = 30513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastwind Rest", description = "I am injured, but we can't stop here.\n\nThe hozen were... unreliable. The pandaren would be much better allies.\n\nYou have seen the refugees in this village, and heard of the yaungol invasion, no?\n\nWell, we've heard from the locals that Eastwind Rest, a nearby village, was destroyed by the Yaungol.\n\nApparently some survivors have gathered along the road out of town.\n\nGo. Take the road west. Gather the survivors. \n\nWe'll help them rebuild. Then, they will see the advantage of joining the Horde!", sourceObjective = "Speak with Farmhand Ko and Elder Shiao in Kun Lai Summit.", progress = "I will not rest until our people are returned and this village rebuilt.", completion = "Well... we are alive, and that is better than we could have hoped for without your help.\n\nBut, if this is truly to become a base of operations for you, and if we are to join your Horde, there is one more thing you must do to guarantee our security.", sourceObjectiveStatus = "unverified-source-field" }
quests[30514] = { id = 30514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", sourceObjective = "Set the Yaungol Banner ablaze to summon Ur-Bataar, and then defeat him in combat.", progress = "As long as Ur-Bataar lives, we cannot have peace.", completion = "You did it! At the very least, we have justice, and safety, though in the process we have lost so much.\n\nRegardless, it has been decided. We will join the Alliance, and with your help, rebuild this village.", sourceObjectiveStatus = "unverified-source-field" }
quests[30515] = { id = 30515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", sourceObjective = "Set the Yaungol Banner at Fire Camp Bataar ablaze to summon Ur-Bataar, and then defeat him in combat.", progress = "As long as Ur-Bataar lives, we cannot have peace.", completion = "You did it! At the very least, we have justice, and safety, though in the process we have lost so much.\n\nRegardless, it has been decided. We will join the Horde, and with your help, rebuild this village.", sourceObjectiveStatus = "unverified-source-field" }
quests[30516] = { id = 30516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm I: A Little Problem", description = "So you need to whack some wily weeds?\n\nNo problem, neighbor! Only thing is, I'm running low on weed killer.\n\nI make my own concoction - very potent, totally organic and good for the earth. Plants love it! Well... except for those pesky weeds. They hate the stuff!\n\nIf you bring me some Spideroot from the terraces just west of us, I'll make a fresh batch and go down to Yoon's farm myself.\n\nI would gather some myself but... well... I hate spiders. You'll see what I mean.", sourceObjective = "Gather 6 Spideroot for Gai Lan.", progress = "How did the root gathering go?", completion = "Well what do we have here? You harvested enough to last me a while.\n\nMany thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[30517] = { id = 30517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer Fung's Vote I: Yak Attack", description = "The next voting member on the Tiller's council is Farmer Fung, and it's easy to see why.\n\nThat man's vegetables are the biggest in the valley! I only hope that someday I can grow pumpkins as big as his.\n\nIf we hope to join the Tillers, he would be the next person to convince.", sourceObjective = "Speak to Farmer Fung at The Heartland or the Halfhill Market in the Valley of the Four Winds.", completion = "Oh? You're with that new farmer in town, aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[30518] = { id = 30518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer Fung's Vote II: On the Loose", description = "You want my vote for Farmer Yoon? Ha! You're joking, right?\n\nListen, I'm not going to vote for some citypaw with no lick a' knowledge about farming the earth.\n\nIt would be an embarrassment to farm alongside you or that Yoon shmuck.\n\nNow let me deal with my own problems. Some devil let my prize yaks loose, and now they're running wild northwest of Halfhill.\n\nIf I could just get my yaks back, then maybe I'd be able to sleep at night.", sourceObjective = "Return 5 Escaped Shagskins to Farmer Fung's yak pen at the very north end of the Verdant Belt.", progress = "What do you want?", completion = "<Farmer Fung stares at you with his jaw on the floor.>\n\nI... I can't believe... YOU recovered all of my prized shagskins!\n\nDo you... do you know what this means to me?\n\nMy family's only been good at two things - raising enormous vegetables and raising yaks.\n\nThe shagskins you see are the result of generations of work.\n\nYou have saved my family's legacy, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30519] = { id = 30519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nana's Vote I: Nana's Secret Recipe", description = "The next vote we'll need is from Nana Mudclaw. She's Haohan's grandmother, and she's been a Tiller longer than you and I have been alive!\n\nShe's still working at the Tillers building in Halfhill. Why don't you pay her a visit?", sourceObjective = "Speak to Nana Mudclaw at Halfhill in the Valley of the Four Winds.", completion = "Yes, Nana Mudclaw... that is me. I may be old, dear, but I haven't lost my memory. Old Man Whitewhiskers, on the other hand, is another story.", sourceObjectiveStatus = "unverified-source-field" }
quests[30521] = { id = 30521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote I: Bungalow Break-In", description = "This is going to be tough, {name}.\n\nThe last vote we need comes from Haohan Mudclaw, the head of the Tillers Union.\n\nI know he wasn't too keen on us to start, but we've learned so much about farming, I'm sure he'll have a change of heart!\n\nGo speak to him. You can be very convincing, right?", sourceObjective = "Speak to Haohan Mudclaw at The Heartland or at Halfhill Market in the Valley of the Four Winds.", completion = "What do you want?", sourceObjectiveStatus = "unverified-source-field" }
quests[30522] = { id = 30522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote II: The Real Culprits", description = "What are YOU doing here, citypaw?\n\nLook, I've got my hands full with a break-in at my shed to the west. Some rascals came in the middle of the night and ransacked the place.\n\nI've got missing seeds, broken tools, and eaten inventory to deal with.\n\nI'll just add it to my list of other troubles: a whole wagon of melons stolen, a broken water pump, animals ruining my harvest...\n\nI wish that I could just get to the bottom of all this already!", sourceObjective = "Investigate 8 Suspicious Footprints.", progress = "How's it going, {name}?", completion = "Hmmm, I'm sorry to hear that Haohan's up to his neck in trouble. Thank you for bringing me this news. Maybe we can help him out.", sourceObjectiveStatus = "unverified-source-field" }
quests[30523] = { id = 30523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm II: The Broken Wagon", description = "Hey {name}. I've been looking at that wagon every day, day in and day out, since the day I moved in. Quite an eyesore, don't you think?\n\nI heard in town that Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we could turn that patch of land into a plot for farming.\n\nWhy don't you talk to her and see if she'd be willing to do the job?", sourceObjective = "Speak to Fish Fellreed at Cattail Lake or the Halfhill Market in the Valley of the Four Winds.", completion = "You need my help fer somethin'? You came to the right gal!", sourceObjectiveStatus = "unverified-source-field" }
quests[30524] = { id = 30524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm II: Knock on Wood", description = "Sure! I know just the wagon that you're talkin' about!\n\nI can fix it right up, but I'll need wood.\n\nThere's a whole lot of it down at the bottom of the lake. If you fish it right out - haha, get it? Fish? Oh I just crack myself up sometimes.\n\nAnyway, you bring me here some 'o that wood and then I'll get right to work!", sourceObjective = "Collect 100 Waxed Planks.", progress = "That lake is plum full o' treasures! You just gotta know what to look for.", completion = "Aww yeah, this wood'll do jus' fine. You did good, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30525] = { id = 30525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote III: Pure Poison", description = "All right, {name}. This is our big chance!\n\nMr. Mudclaw's farm is in big trouble. Those mountain hozen are coming down at night, wrecking his crops and eating his hard-earned harvest.\n\nWe've got to get rid of them for good, and I know just how to do it.\n\nBack in the day, my grandpa showed me how to mix a wounding poison to deal with the pests on the farm.\n\nThe virmen warrens to the north hold the key ingredients for my mixture.\n\nDon't look so worried, {name}! I'm pretty sure this is going to work.", sourceObjective = "Collect 1 Bloodbloom, 1 Cave Lily, 1 Ghostcap, and 1 Violet Lichen.", progress = "The hozen are going to get a big surprise!", completion = "You got the ingredients? Good work!\n\nNow I just need to make the concoction.", sourceObjectiveStatus = "unverified-source-field" }
quests[30526] = { id = 30526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and Lonely", description = "The starving, mangy dog whines piteously and attempts a brief wag of its tail.\n\nIt looks like it could use a good meal right about now.", sourceObjective = "Collect 20 Tasty T-Bone from the Skyrange Mushan on the Skyrange in the Valley of the Four Winds.", progress = "A light comes into the dog's eyes. It seems to recognize you.", completion = "The dog perks its ears up at the sight of the juicy steak.\n\nAs soon as you throw it down, the dog starts eating ravenously.", sourceObjectiveStatus = "unverified-source-field" }
quests[30527] = { id = 30527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote IV: Melons For Felons", description = "All right, now I happen to know that those mountain hozen love a delicious, sweet melon.\n\nMr. Haohan's last harvest of melons got stolen, so we're going to have to grow some of our own.\n\nOnce we have our harvest, we'll use them to lure the nasty hozen's leader out of its cave!", sourceObjective = "Plant and harvest 4 Striped Melons, then deliver 20 Striped Melons to Farmer Yoon.\n\nStriped Melon Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Striped Melons.", progress = "Let's make sure we grow some good melons, {name}. Those crafty hozen only like the sweetest melons.", completion = "Wow, {name}! Those are some big melons. Those are hard to grow, and I should know because I've tried! \n\nI don't know how I would run this place without you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30528] = { id = 30528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote V: Chief Yip-Yip", description = "You ready for the final step of the plan?\n\nThe leader of the Kunzen hozen is a brute by the name of Chief Yip-Yip. It's said that he is nearly impervious to pain.\n\nI've injected the melons with a toxic mixture, so don't try eating them!\n\nOnce you get his attention, throw these melons onto the ground. Yip-Yip won't be able to resist a sweet striped melon.\n\nWhen he takes a bite, he'll be temporarily weakened, and you should find yourself an opening to attack.", sourceObjective = "Kill Chief Yip-Yip at Kunzen Cave to the northwest.", progress = "Did it work? Is Chief Yip-Yip slain?", completion = "The hozen chief is dead? Our plan worked, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30529] = { id = 30529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm III: The Mossy Boulder", description = "Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd be happy to help us upturn this big ole' rock in the middle of our field.\n\nOnce we clear away that stone, I've got something special planned.\n\nRun down and give him a holler to let him know that we're ready.", sourceObjective = "Speak to Haohan Mudclaw in The Heartland or at Halfhill Market in the Valley of the Four Winds.", completion = "Yoon needs a neighbor to lend a hand, eh? Well I'll be plenty happy to oblige.", sourceObjectiveStatus = "unverified-source-field" }
quests[30534] = { id = 30534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Hand", description = "Despite your best efforts, the work is starting to pile up around here.\n\nPerhaps you could ask one of your best friends if they'd like to help out at Sunsong Ranch.", sourceObjective = "Speak to one of your best friends and ask them to work on Sunsong Ranch.", progress = "It's a sturdy rake.", completion = "The talismans on the shrine tinkle softly in the wind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30535] = { id = 30535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow I: Seeds", description = "Well, first things first! I'm going to need lots of help 'round here.\n\nIf we're going to be partners, you've got to learn how to harvest crops, and if you wanna harvest crops you gotta plant seeds!\n\nNow it's my understanding that a mister, uh... Grainfell? No, that wasn't it... Greedfill? That doesn't sound right...\n\nGreenfield! That's his name! He's the man to see for seeds.\n\nGreenfield's got a stall over at Halfhill Market, directly southeast of here - go see him and pick up some vegetable seeds.", sourceObjective = "Speak with Merchant Greenfield at Halfhill Market and acquire a Packet of Green Cabbage Seeds.", progress = "How'd it go, partner? Did you get those seeds from Groanfur?\n\nErr... Greenfield?", completion = "He waved at me! And he gave you the first pack of seeds for free?\n\nWell, what a nice guy!\n\nYou're doing a great job so far. Here's a little... seed money. Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[30538] = { id = 30538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun for the Little Ones" }
quests[30565] = { id = 30565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Advantage", description = "Things seem to be goin' our way more and more lately, {name}. I was out doin some explorin' when I came upon this little beauty.\n\n<Sully gestures to the ballista to his right.>\n\nProblem is she's one of a set and the other one is still in pieces. I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken some of the gears and bolts.\n\nHey, ye seem to be pretty good at handlin' the natives. Ye wouldn't mind goin' and helpin' ol'Sully out would ye?", sourceObjective = "Retrieve the missing Water-Damaged Gears and Rusty Locking Bolts from the Hozen Ambushers to the East.", progress = "Did ye find my missing gears and bolts?", completion = "Well these aren't as good as she deserves, but it will have to work.\n\n<Sully pats the dismantled ballista.>\n\nI'll get 'er up and runnin' in no time, just ye watch!", sourceObjectiveStatus = "unverified-source-field" }
quests[30567] = { id = 30567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blanche's Boomer Brew", description = "Can you smell it in the air? A storm is brewing! And so am I!\n\nMeet me at the hilltop when the storm hits and together we'll whip up a keg of my most famous brew. Can I count on your help?", sourceObjective = "Complete the \"Brewing Storm\" Scenario.", completion = "None too shabby, my {class} friend! We've saved the monastery and still have half a keg left.\n\nThank you for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[30568] = { id = 30568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Cause", description = "Welcome back, {name}! It seems the Jinyu have taken to our training even better than I had hoped. We're in the final stages of our preparations now.\n\nI need someone to go check in with Amber, Bold Karasshi, and Mishka. See if they need any help to complete their training.\n\nYou'll find Karasshi and Mishka here in Pearlfin Village. Amber is training recruits in Slingtail Pits to the northwest.", sourceObjective = "Check in with Bold Karasshi, Amber Kearnen, and Mishka.", progress = "Is everyone in order and ready to move?", completion = "Impressive work, {name}. We should be ready to move out shortly. With our allies at our side, there is no way we can be defeated.", sourceObjectiveStatus = "unverified-source-field" }
quests[30569] = { id = 30569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him out. Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", sourceObjective = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit.", completion = "You're a sight for sore eyes, {class}.\n\nI'll be glad to help you Alliance fellas out. First though, you need to help me get my farm back.", sourceObjectiveStatus = "unverified-source-field" }
quests[30570] = { id = 30570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him... Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", sourceObjective = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit.", completion = "You're a sight for sore eyes, {class}.\n\nI'll be glad to help you Horde fellas out. First though, you need to help me get my farm back.", sourceObjectiveStatus = "unverified-source-field" }
quests[30571] = { id = 30571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmhand Freedom", description = "Those Ordo yaungol are working my farmhands to death! It just ain't right.\n\nPlease, {class}, save them before it's too late.", sourceObjective = "Free 12 Farmstead Slaves by killing Ordo Overseers.", progress = "Look, mister, I don't mean to be telling you your business, but I can still see a lot of my farmhands still out there.", completion = "Now ain't you just the thing?\n\nThough, I guess it's not fair to force these here workers to stay with us, now that we don't have much work for 'em...", sourceObjectiveStatus = "unverified-source-field" }
quests[30575] = { id = 30575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 'Em Up", description = "Mobility is going to be key to maintaining our foothold in this new land. Problem is, there's no way to maintain mobility without mounts, and... well, we don't have many of those here, now do we?\n\nThe local yaks seem to make good mounts. At least, the local pandaren say they do. Why don't you go round some up for us?", sourceObjective = "Round up 3 Wild Plains Yaks and return them to Westwind Rest.", progress = "It's going to take more yaks than that to get this place back into fightin' condition, {name}, yes it is.", completion = "These yaks will do the trick nicely. Good work, {name}. I'm feeling better about this whole situation already.", sourceObjectiveStatus = "unverified-source-field" }
quests[30581] = { id = 30581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... and the Pot, Too!", description = "Sure, I'm willing to help you guys out. But we need to eat, too! I don't even have a pot to cook in! Let alone ingredients to put in it!\n\nHere's a list of the things that I need. Now get!", sourceObjective = "Collect 12 Root Vegetables and 1 Cast Iron Pot.", progress = "Do you have everything from the list?!", completion = "Well there you go. We should be plenty good, now.", sourceObjectiveStatus = "unverified-source-field" }
quests[30582] = { id = 30582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Late Mrs. Muskpaw", description = "This well worn trinket has several markings on it confessing love and adoration from the late Mrs. Muskpaw.\n\nPerhaps Lao would like his wife's trinket back.", sourceObjective = "Bring the Muskpaw Keepsake to Lao Muskpaw.", progress = "Oh, and what have you there.", completion = "Ya never know how much you can lose until you've lost it. My wife passed a few seasons ago, but I can tell you this is a day when I could use her smile the most.\n\nAt least she doesn't have to see what these yaungol did to her beloved ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30583] = { id = 30583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blue Dwarf Needs Food Badly", description = "Oi!\n\nWe need ta' get us some food, if we're gonna survive here for long!\n\nYe' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, at least.", sourceObjective = "Collect 160 Kun-Lai Meaty Bits.", progress = "Well... ya' got my meat?", completion = "Good work! I'm telliin' ye, these Kun-Lai meaty bits are grade A goodness!", sourceObjectiveStatus = "unverified-source-field" }
quests[30584] = { id = 30584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shocking!", description = "Have you ever had a fresh dojani eel {name}?  No?\n\nWell you have not lived then!  Head north up to the dojani river and fish up a few for us.   Be careful, those eels can zap you if you're not careful!", sourceObjective = "Fish up 7 Dojani Eels from the Dojani River in Krasarang Wilds.", progress = "Were you able to catch the eels?", completion = "These look like some tasty eels {name}!  I'm sure you will love them!", sourceObjectiveStatus = "unverified-source-field" }
quests[30585] = { id = 30585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lurks Below", description = "Legend tells of a great beast in the forest to the north.  My son is missing and I fear he may have wandered too near its lair....\n\nHead northwest to Krasari Falls and look for a mysterious whirlpool - this is the key to revealing what is hidden there.  Kill the wretched beast and recover any clues to my son's whereabouts.", sourceObjective = "Find an Ancient Fishing Pool at Krasari Falls to the northwest and fish in it to lure the beast out of hiding.", progress = "What news of my son?", completion = "My son's ring?  What does this mean?\n\n<Rassan appears thoughtful.>\n\nThe situation is grim, but not without hope.  My son is careless with his belongings, so perhaps he simply threw it into the pool?  Thank you for your help {name}, I will not soon forget this great favor you have done for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[30586] = { id = 30586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagged Abalone", description = "Pandaren have been harvesting jagged abalone in this area for generations.  Now it's time for you to learn the ritual.\n\nThe abalone can be found just northeast of here in narsong trench.  Be careful, we have noticed increased shark activity in that area recently.", sourceObjective = "Harvest 9 Jagged Abalone Meat from the Jagged Abalone in Narsong Trench to the northeast.", progress = "Did you see any sharks down there?", completion = "Oh!  Looks like you found plenty of abalone out there.  Great job {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30587] = { id = 30587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yakity Yak", description = "For now, the yaungol invaders seem content to steal yaks. Surveying the area, however, you notice they could easily move on the Yak Wash at any moment.\n\nThinning their numbers may help show the yaungol that this area is protected.", sourceObjective = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch.", progress = "Them yak stealing, ranch smashing, bad breath yaungols gotta learn a thing or two about attacking decent folk.", completion = "Well then, I am mighty grateful for you culling some of those yaungols for us.\n\nHopefully your little display of authority will be enough to discourage them from coming over here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30588] = { id = 30588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing for a Bruising", description = "The riverblade saurok clan is attacking one of our local fishing expeditions!  They need help right away!\n\nThin those saurok out and help that expedition return safely!", sourceObjective = "Kill 8 Riverblade Beach Raiders at Anglers Expedition, just west of Anglers Wharf.", progress = "Any luck with those saurok?", completion = "The expedition is safe.  Thank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30589] = { id = 30589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrecking the Wreck", description = "To dislodge the alliance ship, we need to find our engineer. He parted ways with us when we were escaping the wreckage.\n\nYou should be able to find him somewhere in the western forest. Tell him Korga sent you and he'll get in line to help.", sourceObjective = "Speak to Makael Bay in the Pei-Wu Forest.", completion = "Korga sent you, eh? Well, I wouldn't mind doing a number on that ship for my own reasons anyway, but it's going to take some work.\n\nGive me a moment to think...", sourceObjectiveStatus = "unverified-source-field" }
quests[30590] = { id = 30590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handle With Care", description = "We can help you get your ship free, but we'll need more of the explosives we were trying to take back from the Alliance to make it happen.\n\nI ordered the men to grab all the explosives they could before making our escape. If you sift through the wreckage and bodies to our south, there should be some explosive bundles among them, those that didn't already blow up anyway.\n\nGet me enough of them and I think I can put something together for ya.", sourceObjective = "Recover 6 Packed Explosive Charges.", progress = "You're in one piece. That's a good sign.\n\nDid you get your hands on what I asked for?", completion = "More than enough. I've got the main control panel constructed. We should be ready very soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[30591] = { id = 30591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying on the Predators", description = "The forest has become far more dangerous ever since Shen-zin Su began shaking. The tigers are agitated and have begun attacking the refugees, and on occasion, me as well.\n\nIf these injured and weak survivors are to make it to safety here at the hut, we need to help clear the forest for them.", sourceObjective = "Kill 9 Pei-Wu Tigers.", completion = "These survivors are in your debt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
